#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>
#include <ctype.h>
static size_t ng_test_fail_after_count;
static int ng_test_failure_enabled;
enum ng_test_import_stage { NG_TEST_IMPORT_NONE=0, NG_TEST_IMPORT_SNAPSHOT, NG_TEST_IMPORT_PARSE_NODES, NG_TEST_IMPORT_SYMBOL, NG_TEST_IMPORT_NODE, NG_TEST_IMPORT_LABEL, NG_TEST_IMPORT_NODE_PROPERTY, NG_TEST_IMPORT_PARSE_RELATIONSHIPS, NG_TEST_IMPORT_RELATIONSHIP, NG_TEST_IMPORT_RELATIONSHIP_PROPERTY, NG_TEST_IMPORT_ADJACENCY, NG_TEST_IMPORT_COMPLETE };
static enum ng_test_import_stage ng_test_import_stage;
enum ng_test_import_stage ng_test_import_last_stage(void){return ng_test_import_stage;}
void ng_test_fail_after(size_t count){ng_test_import_stage=NG_TEST_IMPORT_NONE;ng_test_fail_after_count=count;ng_test_failure_enabled=1;}
void ng_test_fail_reset(void){ng_test_fail_after_count=0;ng_test_failure_enabled=0;}
static ng_status ng_test_maybe_fail(void){if(!ng_test_failure_enabled)return NG_OK;if(ng_test_fail_after_count==0){ng_test_failure_enabled=0;return NG_OOM;}ng_test_fail_after_count--;return NG_OK;}
static uint64_t ng_test_import_stage_mask_value;
static void ng_test_set_import_stage(enum ng_test_import_stage stage){ng_test_import_stage=stage;ng_test_import_stage_mask_value|=((uint64_t)1u<<((unsigned)stage));}
enum ng_test_import_stage ng_test_import_current_stage(void){return ng_test_import_stage;}
uint64_t ng_test_import_stage_mask(void){return ng_test_import_stage_mask_value;}

typedef struct { ng_symbol_id id; char *s; } sym;
typedef struct { ng_symbol_id key; ng_value v; } prop;
typedef struct { ng_id id; ng_symbol_id *labels; size_t nl,np,cap; prop *p; } node_i;
typedef struct { ng_id id,src,dst; ng_symbol_id type; size_t np,cap; prop *p; } rel_i;
typedef struct { ng_node_constraint_kind kind; ng_symbol_id label,key; } constraint_i;
typedef struct { ng_symbol_id label,key; } index_i;
struct ng_graph { char *path; uint64_t next_node,next_rel,next_sym; sym *sy; size_t ns,cs; node_i *no; size_t nn,cn; rel_i *re; size_t nr,cr; constraint_i *co; size_t nc,cc; index_i *ix; size_t nix,cix; size_t *ao; size_t *ai; size_t an; };
struct ng_transaction { ng_graph *target; ng_graph working; int active; };
typedef struct { ng_node_id id; ng_value value; } ng_node_index_entry;
struct ng_node_index { ng_symbol_id label,key; ng_node_index_entry *entries; size_t count,cap; };
static ng_status ng_validate_constraints_all(const ng_graph*g);
static int ng_value_equal(const ng_value*a,const ng_value*b);
static int ng_node_matches_label(const node_i*n,ng_symbol_id label);
static int grow(void **p,size_t *cap,size_t n,size_t z){size_t c=*cap?*cap:8;if(ng_test_maybe_fail()!=NG_OK)return 0;if(n>SIZE_MAX/z)return 0;while(c<n){if(c>SIZE_MAX/2)return 0;c*=2;}void *q=realloc(*p,c*z);if(!q)return 0;*p=q;*cap=c;return 1;}
static char *dupstr(const char *s){size_t n;if(ng_test_maybe_fail()!=NG_OK)return NULL;n=strlen(s)+1;char *p=(char*)malloc(n);if(p)memcpy(p,s,n);return p;}
static ng_status init(ng_graph **out,const char *path){ng_graph *g=(ng_graph*)calloc(1,sizeof(*g));if(!g)return NG_OOM;g->path=dupstr(path);if(!g->path){free(g);return NG_OOM;}g->next_node=g->next_rel=g->next_sym=1;*out=g;return NG_OK;}
ng_status ng_create(ng_graph **o,const char *p){if(!o||!p)return NG_INVALID_ARGUMENT;return init(o,p);}
static void put64(unsigned char *p,uint64_t v){size_t i;for(i=0;i<8;i++){p[i]=(unsigned char)(v&255u);v>>=8;}}
static uint64_t get64(const unsigned char *p){uint64_t v=0;size_t i;for(i=0;i<8;i++)v|=((uint64_t)p[i])<<(8*i);return v;}
static uint32_t hash32(const unsigned char *p,size_t n){uint32_t h=2166136261u;while(n--)h=(h^*p++)*16777619u;return h;}
typedef struct {unsigned char *p;size_t n,c;} blob;
static int add(blob*b,const void*p,size_t n){if(n>SIZE_MAX-b->n)return 0;if(b->n+n>b->c){size_t c=b->c?b->c:256;void *q;while(c<b->n+n){if(c>SIZE_MAX/2)return 0;c*=2;}q=realloc(b->p,c);if(!q)return 0;b->p=(unsigned char*)q;b->c=c;}memcpy(b->p+b->n,p,n);b->n+=n;return 1;}
static int a64(blob*b,uint64_t v){unsigned char x[8];put64(x,v);return add(b,x,8);}
static int astr(blob*b,const char*s,size_t n){return a64(b,n)&&add(b,s,n);}
static int avalue(blob*b,const ng_value*v){if(!a64(b,(uint64_t)v->type)||!a64(b,v->length))return 0;if(v->type==NG_VALUE_STRING)return add(b,v->as.string,v->length);if(v->type==NG_VALUE_BYTES)return add(b,v->as.bytes,v->length);if(v->type==NG_VALUE_BOOL)return a64(b,(uint64_t)v->as.boolean);if(v->type==NG_VALUE_INT64)return a64(b,(uint64_t)v->as.integer);if(v->type==NG_VALUE_DOUBLE){uint64_t u;memcpy(&u,&v->as.real,8);return a64(b,u);}return 1;}
static int aprop(blob*b,const prop*p){return a64(b,p->key)&&avalue(b,&p->v);}
ng_status ng_save(ng_graph *g){blob b={0,0,0};FILE*f;char tmp[4096];size_t i,j;unsigned char h[32];ng_status vs;if(!g)return NG_INVALID_ARGUMENT;vs=ng_validate(g);if(vs!=NG_OK)return vs;if(strlen(g->path)>sizeof(tmp)-6)return NG_INVALID_ARGUMENT;if(!a64(&b,g->ns)||!a64(&b,g->nn)||!a64(&b,g->nr)||!a64(&b,g->nc)||!a64(&b,g->nix)||!a64(&b,g->next_sym)||!a64(&b,g->next_node)||!a64(&b,g->next_rel))goto oom;for(i=0;i<g->ns;i++)if(!a64(&b,g->sy[i].id)||!astr(&b,g->sy[i].s,strlen(g->sy[i].s)))goto oom;for(i=0;i<g->nn;i++){node_i*n=&g->no[i];if(!a64(&b,n->id)||!a64(&b,n->nl))goto oom;for(j=0;j<n->nl;j++)if(!a64(&b,n->labels[j]))goto oom;if(!a64(&b,n->np))goto oom;for(j=0;j<n->np;j++)if(!aprop(&b,&n->p[j]))goto oom;}for(i=0;i<g->nr;i++){rel_i*r=&g->re[i];if(!a64(&b,r->id)||!a64(&b,r->src)||!a64(&b,r->dst)||!a64(&b,r->type)||!a64(&b,r->np))goto oom;for(j=0;j<r->np;j++)if(!aprop(&b,&r->p[j]))goto oom;}for(i=0;i<g->nc;i++)if(!a64(&b,(uint64_t)g->co[i].kind)||!a64(&b,g->co[i].label)||!a64(&b,g->co[i].key))goto oom;for(i=0;i<g->nix;i++)if(!a64(&b,g->ix[i].label)||!a64(&b,g->ix[i].key))goto oom;memcpy(h,"NAUTY",5);h[5]=3;put64(h+8,(uint64_t)b.n);put64(h+16,g->next_node^g->next_rel^g->next_sym);put64(h+24,hash32(b.p,b.n));(void)snprintf(tmp,sizeof(tmp),"%s.tmp",g->path);f=fopen(tmp,"wb");if(!f||fwrite(h,1,32,f)!=32||fwrite(b.p,1,b.n,f)!=b.n||fclose(f)!=0){if(f)fclose(f);remove(tmp);free(b.p);return NG_IO_ERROR;}if(rename(tmp,g->path)!=0){remove(tmp);free(b.p);return NG_IO_ERROR;}free(b.p);return NG_OK;oom:free(b.p);return NG_OOM;}
typedef struct {const unsigned char*p;size_t n,o;} cursor;
static int take64(cursor*c,uint64_t*v){if(c->o>c->n||c->n-c->o<8)return 0;*v=get64(c->p+c->o);c->o+=8;return 1;}
static int take_bytes(cursor*c,const unsigned char**p,size_t n){if(n>c->n-c->o)return 0;*p=c->p+c->o;c->o+=n;return 1;}
static int load_value(cursor*c,ng_value*v){uint64_t t,n,u;const unsigned char*p;if(!take64(c,&t)||!take64(c,&n)||t>NG_VALUE_BYTES||n>SIZE_MAX)return 0;memset(v,0,sizeof(*v));v->type=(ng_value_type)t;v->length=(size_t)n;if(t==NG_VALUE_STRING){if(!take_bytes(c,&p,v->length))return 0;v->as.string=(char*)malloc(v->length+1);if(!v->as.string)return 0;memcpy((char*)v->as.string,p,v->length);((char*)v->as.string)[v->length]=0;}else if(t==NG_VALUE_BYTES){if(!take_bytes(c,&p,v->length))return 0;v->as.bytes=(unsigned char*)malloc(v->length);if(v->length&&!v->as.bytes)return 0;memcpy((unsigned char*)v->as.bytes,p,v->length);}else if(t==NG_VALUE_BOOL||t==NG_VALUE_INT64||t==NG_VALUE_DOUBLE){if(!take64(c,&u))return 0;if(t==NG_VALUE_BOOL)v->as.boolean=(int)u;else if(t==NG_VALUE_INT64)v->as.integer=(int64_t)u;else memcpy(&v->as.real,&u,8);}return 1;}
ng_status ng_open(ng_graph **o,const char*p){FILE*f;unsigned char h[32],*d;uint64_t z,ns,nn,nr,nc=0,nix=0;size_t i,j;cursor c;ng_status s;if(!o||!p)return NG_INVALID_ARGUMENT;s=init(o,p);if(s!=NG_OK)return s;f=fopen(p,"rb");if(!f)return NG_OK;if(fread(h,1,32,f)!=32||memcmp(h,"NAUTY",5)!=0||(h[5]!=1&&h[5]!=2&&h[5]!=3)){fclose(f);ng_close(*o);return NG_CORRUPT;}z=get64(h+8);if(z>SIZE_MAX){fclose(f);ng_close(*o);return NG_CORRUPT;}d=(unsigned char*)malloc((size_t)z);if(z&&!d){fclose(f);ng_close(*o);return NG_OOM;}if(fread(d,1,(size_t)z,f)!=(size_t)z){free(d);fclose(f);ng_close(*o);return NG_CORRUPT;}if(fgetc(f)!=EOF||ferror(f)){free(d);fclose(f);ng_close(*o);return NG_CORRUPT;}fclose(f);if(hash32(d,(size_t)z)!=(uint32_t)get64(h+24)){free(d);ng_close(*o);return NG_CORRUPT;}c.p=d;c.n=(size_t)z;c.o=0;if(!take64(&c,&ns)||!take64(&c,&nn)||!take64(&c,&nr)||(h[5]>=2&&!take64(&c,&nc))||(h[5]>=3&&!take64(&c,&nix))||!take64(&c,&(*o)->next_sym)||!take64(&c,&(*o)->next_node)||!take64(&c,&(*o)->next_rel)||ns>SIZE_MAX||nn>SIZE_MAX||nr>SIZE_MAX||nc>SIZE_MAX||nix>SIZE_MAX){free(d);ng_close(*o);return NG_CORRUPT;}
for(i=0;i<(size_t)ns;i++){uint64_t id,len;const unsigned char *q;if(!take64(&c,&id)||!take64(&c,&len)||len>SIZE_MAX||!take_bytes(&c,&q,(size_t)len)||memchr(q,0,(size_t)len)){free(d);ng_close(*o);return NG_CORRUPT;}if(!grow((void**)&(*o)->sy,&(*o)->cs,(*o)->ns+1,sizeof(*(*o)->sy))){free(d);ng_close(*o);return NG_OOM;}(*o)->sy[(*o)->ns].id=id;(*o)->sy[(*o)->ns].s=(char*)malloc((size_t)len+1);if(!(*o)->sy[(*o)->ns].s){free(d);ng_close(*o);return NG_OOM;}memcpy((*o)->sy[(*o)->ns].s,q,(size_t)len);(*o)->sy[(*o)->ns].s[len]=0;(*o)->ns++;}
for(i=0;i<(size_t)nn;i++){node_i *x;uint64_t id,nl,np;if(!take64(&c,&id)||!take64(&c,&nl)||nl>SIZE_MAX||!grow((void**)&(*o)->no,&(*o)->cn,(*o)->nn+1,sizeof(*(*o)->no))){free(d);ng_close(*o);return NG_CORRUPT;}x=&(*o)->no[(*o)->nn++];memset(x,0,sizeof(*x));x->id=id;x->nl=(size_t)nl;if(nl){x->labels=malloc((size_t)nl*sizeof(*x->labels));if(!x->labels){free(d);ng_close(*o);return NG_OOM;}for(j=0;j<(size_t)nl;j++)if(!take64(&c,(uint64_t*)&x->labels[j])){free(d);ng_close(*o);return NG_CORRUPT;}}if(!take64(&c,&np)||np>SIZE_MAX){free(d);ng_close(*o);return NG_CORRUPT;}for(j=0;j<(size_t)np;j++){uint64_t key;if(!take64(&c,&key)||!grow((void**)&x->p,&x->cap,x->np+1,sizeof(*x->p))||!load_value(&c,&x->p[x->np].v)){free(d);ng_close(*o);return NG_CORRUPT;}x->p[x->np++].key=key;}}
for(i=0;i<(size_t)nr;i++){rel_i *r;uint64_t np;if(!grow((void**)&(*o)->re,&(*o)->cr,(*o)->nr+1,sizeof(*(*o)->re))){free(d);ng_close(*o);return NG_OOM;}r=&(*o)->re[(*o)->nr++];memset(r,0,sizeof(*r));if(!take64(&c,&r->id)||!take64(&c,&r->src)||!take64(&c,&r->dst)||!take64(&c,&r->type)||!take64(&c,&np)||np>SIZE_MAX){free(d);ng_close(*o);return NG_CORRUPT;}for(j=0;j<(size_t)np;j++){uint64_t key;if(!take64(&c,&key)||!grow((void**)&r->p,&r->cap,r->np+1,sizeof(*r->p))||!load_value(&c,&r->p[r->np].v)){free(d);ng_close(*o);return NG_CORRUPT;}r->p[r->np++].key=key;}}for(i=0;i<(size_t)nc;i++){uint64_t kind,label,key;if(!take64(&c,&kind)||!take64(&c,&label)||!take64(&c,&key)||!grow((void**)&(*o)->co,&(*o)->cc,(*o)->nc+1,sizeof(*(*o)->co))){free(d);ng_close(*o);return NG_CORRUPT;}(*o)->co[(*o)->nc].kind=(ng_node_constraint_kind)kind;(*o)->co[(*o)->nc].label=label;(*o)->co[(*o)->nc].key=key;(*o)->nc++;}for(i=0;i<(size_t)nix;i++){uint64_t label,key;if(!take64(&c,&label)||!take64(&c,&key)||!grow((void**)&(*o)->ix,&(*o)->cix,(*o)->nix+1,sizeof(*(*o)->ix))){free(d);ng_close(*o);return NG_CORRUPT;}(*o)->ix[(*o)->nix].label=label;(*o)->ix[(*o)->nix].key=key;(*o)->nix++;}if(c.o!=c.n){free(d);ng_close(*o);return NG_CORRUPT;}free(d);return ng_validate(*o);}
static void valfree(ng_value *v){if(v->type==NG_VALUE_STRING||v->type==NG_VALUE_BYTES)free((void*)(v->type==NG_VALUE_STRING?(void*)v->as.string:(void*)v->as.bytes));}
static ng_status valcopy(ng_value *dst,const ng_value *src){*dst=*src;if(src->type==NG_VALUE_STRING){dst->as.string=dupstr(src->as.string);if(!dst->as.string)return NG_OOM;}else if(src->type==NG_VALUE_BYTES){dst->as.bytes=(unsigned char*)malloc(src->length);if(src->length&&!dst->as.bytes)return NG_OOM;memcpy((void*)dst->as.bytes,src->as.bytes,src->length);}return NG_OK;}
static int ng_valid_value(const ng_value*v){if(!v||v->type>NG_VALUE_BYTES)return 0;if(v->type==NG_VALUE_BOOL&&(v->as.boolean!=0&&v->as.boolean!=1))return 0;if(v->type==NG_VALUE_STRING&&v->length&&!v->as.string)return 0;if(v->type==NG_VALUE_BYTES&&v->length&&!v->as.bytes)return 0;return 1;}
void ng_close(ng_graph *g){size_t i,j;if(!g)return;for(i=0;i<g->ns;i++){free(g->sy[i].s);}for(i=0;i<g->nn;i++){free(g->no[i].labels);for(j=0;j<g->no[i].np;j++)valfree(&g->no[i].p[j].v);free(g->no[i].p);}for(i=0;i<g->nr;i++){for(j=0;j<g->re[i].np;j++)valfree(&g->re[i].p[j].v);free(g->re[i].p);}free(g->sy);free(g->no);free(g->re);free(g->co);free(g->ix);free(g->ao);free(g->ai);free(g->path);free(g);}
ng_status ng_symbol(ng_graph *g,const char *s,ng_symbol_id *o){size_t i;char *copy;if(!g||!s||!o)return NG_INVALID_ARGUMENT;for(i=0;i<g->ns;i++)if(!strcmp(g->sy[i].s,s)){*o=g->sy[i].id;return NG_OK;}copy=dupstr(s);if(!copy)return NG_OOM;if(!grow((void**)&g->sy,&g->cs,g->ns+1,sizeof(*g->sy))){free(copy);return NG_OOM;}g->sy[g->ns].id=g->next_sym++;g->sy[g->ns].s=copy;*o=g->sy[g->ns++].id;return NG_OK;}
static node_i *node(ng_graph *g,ng_id id){size_t i;for(i=0;i<g->nn;i++)if(g->no[i].id==id)return &g->no[i];return NULL;}
static const prop *findprop(const prop *p,size_t n,ng_symbol_id k){size_t i;for(i=0;i<n;i++)if(p[i].key==k)return &p[i];return NULL;}
ng_status ng_node_create(ng_graph *g,const ng_symbol_id *l,size_t n,ng_id *o){node_i *x;ng_symbol_id *labels=NULL;size_t i;if(!g||!o||(n&& !l))return NG_INVALID_ARGUMENT;for(i=0;i<n;i++)if(!l[i]||!ng_symbol_name(g,l[i]))return NG_NOT_FOUND;if(n){labels=(ng_symbol_id*)malloc(n*sizeof(*l));if(!labels)return NG_OOM;memcpy(labels,l,n*sizeof(*l));}if(!grow((void**)&g->no,&g->cn,g->nn+1,sizeof(*g->no))){free(labels);return NG_OOM;}x=&g->no[g->nn++];memset(x,0,sizeof(*x));x->id=g->next_node++;x->labels=labels;x->nl=n;*o=x->id;return NG_OK;}
ng_status ng_relationship_create(ng_graph *g,ng_id a,ng_symbol_id t,ng_id b,ng_id *o){rel_i *r;if(!g||!o||!node(g,a)||!node(g,b)||!t)return NG_INVALID_ARGUMENT;if(!ng_symbol_name(g,t))return NG_NOT_FOUND;if(!grow((void**)&g->re,&g->cr,g->nr+1,sizeof(*g->re)))return NG_OOM;r=&g->re[g->nr++];memset(r,0,sizeof(*r));r->id=g->next_rel++;r->src=a;r->dst=b;r->type=t;*o=r->id;return NG_OK;}
ng_status ng_relationship_delete(ng_graph*g,ng_relationship_id id){size_t i,j;if(!g)return NG_INVALID_ARGUMENT;for(i=0;i<g->nr;i++)if(g->re[i].id==id){for(j=0;j<g->re[i].np;j++)valfree(&g->re[i].p[j].v);free(g->re[i].p);if(i+1<g->nr)memmove(&g->re[i],&g->re[i+1],(g->nr-i-1)*sizeof(*g->re));g->nr--;return NG_OK;}return NG_NOT_FOUND;}
ng_status ng_node_delete(ng_graph*g,ng_node_id id){size_t i,j;if(!g)return NG_INVALID_ARGUMENT;for(i=0;i<g->nn;i++)if(g->no[i].id==id){for(j=g->nr;j>0;j--)if(g->re[j-1].src==id||g->re[j-1].dst==id)ng_relationship_delete(g,g->re[j-1].id);free(g->no[i].labels);for(j=0;j<g->no[i].np;j++)valfree(&g->no[i].p[j].v);free(g->no[i].p);if(i+1<g->nn)memmove(&g->no[i],&g->no[i+1],(g->nn-i-1)*sizeof(*g->no));g->nn--;return NG_OK;}return NG_NOT_FOUND;}
static ng_status setprop(prop **pp,size_t *n,size_t *cap,ng_symbol_id k,const ng_value *v){size_t i;prop *p;ng_value copy;if(!v||!k)return NG_INVALID_ARGUMENT;copy=*v;if(v->type==NG_VALUE_STRING){copy.as.string=dupstr(v->as.string);if(!copy.as.string)return NG_OOM;}else if(v->type==NG_VALUE_BYTES){copy.as.bytes=(unsigned char*)malloc(v->length);if(v->length&&!copy.as.bytes)return NG_OOM;memcpy((void*)copy.as.bytes,v->as.bytes,v->length);}for(i=0;i<*n;i++)if((*pp)[i].key==k){valfree(&(*pp)[i].v);(*pp)[i].v=copy;return NG_OK;}if(!grow((void**)pp,cap,*n+1,sizeof(**pp))){valfree(&copy);return NG_OOM;}p=&(*pp)[(*n)++];p->key=k;p->v=copy;return NG_OK;}
static ng_status ng_node_set_constraint_check(const ng_graph*g,const node_i*n,ng_symbol_id k,const ng_value*v){size_t i,j;for(i=0;i<g->nc;i++)if(g->co[i].key==k&&ng_node_matches_label(n,g->co[i].label)){if(g->co[i].kind==NG_NODE_CONSTRAINT_REQUIRED_PROPERTY&&v->type==NG_VALUE_NULL)return NG_NOT_FOUND;if(g->co[i].kind==NG_NODE_CONSTRAINT_UNIQUE_PROPERTY&&v->type!=NG_VALUE_NULL)for(j=0;j<g->nn;j++){const prop*p;if(g->no[j].id==n->id||!ng_node_matches_label(&g->no[j],g->co[i].label))continue;p=findprop(g->no[j].p,g->no[j].np,k);if(p&&p->v.type!=NG_VALUE_NULL&&ng_value_equal(&p->v,v))return NG_EXISTS;}}return NG_OK;}
static int ng_node_unset_allowed(const ng_graph*g,const node_i*n,ng_symbol_id k){size_t i;for(i=0;i<g->nc;i++)if(g->co[i].kind==NG_NODE_CONSTRAINT_REQUIRED_PROPERTY&&g->co[i].key==k&&ng_node_matches_label(n,g->co[i].label))return 0;return 1;}
ng_status ng_node_set(ng_graph*g,ng_id id,ng_symbol_id k,const ng_value*v){node_i*n=g?node(g,id):NULL;ng_status s;if(!g||!v||!k)return NG_INVALID_ARGUMENT;if(v->type>NG_VALUE_BYTES||(v->type==NG_VALUE_STRING&&!v->as.string)||(v->type==NG_VALUE_BYTES&&v->length&&!v->as.bytes))return NG_INVALID_ARGUMENT;if(!n)return NG_NOT_FOUND;if(!ng_symbol_name(g,k))return NG_NOT_FOUND;s=ng_node_set_constraint_check(g,n,k,v);if(s!=NG_OK)return s;return setprop(&n->p,&n->np,&n->cap,k,v);}
static int ng_label_list_matches(const ng_symbol_id*l,size_t n,ng_symbol_id label){size_t i;if(!label)return 1;for(i=0;i<n;i++)if(l[i]==label)return 1;return 0;}
static const ng_value *ng_property_list_find(const ng_property*p,size_t n,ng_symbol_id key){size_t i;for(i=0;i<n;i++)if(p[i].key==key)return &p[i].value;return NULL;}
static ng_status ng_node_create_properties_check(const ng_graph*g,const ng_symbol_id*l,size_t nl,const ng_property*p,size_t np){size_t i,j;if(!g||(nl&&!l)||(np&&!p))return NG_INVALID_ARGUMENT;for(i=0;i<nl;i++){if(!l[i]||!ng_symbol_name(g,l[i]))return NG_NOT_FOUND;for(j=0;j<i;j++)if(l[j]==l[i])return NG_INVALID_ARGUMENT;}for(i=0;i<np;i++){if(!p[i].key)return NG_INVALID_ARGUMENT;if(!ng_symbol_name(g,p[i].key))return NG_NOT_FOUND;if(!ng_valid_value(&p[i].value)||(p[i].value.type==NG_VALUE_STRING&&!p[i].value.as.string)||(p[i].value.type==NG_VALUE_BYTES&&p[i].value.length&&!p[i].value.as.bytes))return NG_INVALID_ARGUMENT;for(j=0;j<i;j++)if(p[j].key==p[i].key)return NG_INVALID_ARGUMENT;}for(i=0;i<g->nc;i++)if(ng_label_list_matches(l,nl,g->co[i].label)){const ng_value*v=ng_property_list_find(p,np,g->co[i].key);if(g->co[i].kind==NG_NODE_CONSTRAINT_REQUIRED_PROPERTY&&(!v||v->type==NG_VALUE_NULL))return NG_NOT_FOUND;if(g->co[i].kind==NG_NODE_CONSTRAINT_UNIQUE_PROPERTY&&v&&v->type!=NG_VALUE_NULL)for(j=0;j<g->nn;j++){const prop*x;if(!ng_node_matches_label(&g->no[j],g->co[i].label))continue;x=findprop(g->no[j].p,g->no[j].np,g->co[i].key);if(x&&x->v.type!=NG_VALUE_NULL&&ng_value_equal(&x->v,v))return NG_EXISTS;}}return NG_OK;}
ng_status ng_node_create_with_properties(ng_graph*g,const ng_symbol_id*l,size_t nl,const ng_property*p,size_t np,ng_node_id*out){ng_node_id id;size_t i;ng_status s;if(!out)return NG_INVALID_ARGUMENT;s=ng_node_create_properties_check(g,l,nl,p,np);if(s!=NG_OK)return s;s=ng_node_create(g,l,nl,&id);if(s!=NG_OK)return s;for(i=0;i<np;i++){s=ng_node_set(g,id,p[i].key,&p[i].value);if(s!=NG_OK){ng_node_delete(g,id);return s;}}*out=id;return NG_OK;}
ng_status ng_relationship_set(ng_graph*g,ng_id id,ng_symbol_id k,const ng_value*v){size_t i;if(!g||!v)return NG_INVALID_ARGUMENT;if(v->type>NG_VALUE_BYTES||(v->type==NG_VALUE_STRING&&!v->as.string)||(v->type==NG_VALUE_BYTES&&v->length&&!v->as.bytes))return NG_INVALID_ARGUMENT;for(i=0;i<g->nr;i++)if(g->re[i].id==id)return setprop(&g->re[i].p,&g->re[i].np,&g->re[i].cap,k,v);return NG_NOT_FOUND;}
static ng_status unsetprop(prop *p,size_t *n,ng_symbol_id k){size_t i;if(!k)return NG_INVALID_ARGUMENT;for(i=0;i<*n;i++)if(p[i].key==k){valfree(&p[i].v);if(i+1<*n)memmove(&p[i],&p[i+1],(*n-i-1)*sizeof(*p));(*n)--;return NG_OK;}return NG_NOT_FOUND;}
ng_status ng_node_unset(ng_graph*g,ng_node_id id,ng_symbol_id k){node_i*n;if(!g||!k)return NG_INVALID_ARGUMENT;n=node(g,id);if(!n)return NG_NOT_FOUND;if(!ng_symbol_name(g,k))return NG_NOT_FOUND;if(!ng_node_unset_allowed(g,n,k))return NG_NOT_FOUND;return unsetprop(n->p,&n->np,k);}
ng_status ng_relationship_unset(ng_graph*g,ng_relationship_id id,ng_symbol_id k){size_t i;if(!g)return NG_INVALID_ARGUMENT;for(i=0;i<g->nr;i++)if(g->re[i].id==id)return unsetprop(g->re[i].p,&g->re[i].np,k);return NG_NOT_FOUND;}
size_t ng_node_count(const ng_graph*g){return g?g->nn:0;} size_t ng_relationship_count(const ng_graph*g){return g?g->nr:0;}
size_t ng_symbol_count(const ng_graph*g){return g?g->ns:0;}
ng_status ng_node_get(const ng_graph*g,ng_node_id id,ng_node*out){size_t i;if(!g||!out)return NG_INVALID_ARGUMENT;for(i=0;i<g->nn;i++)if(g->no[i].id==id){out->id=id;return NG_OK;}return NG_NOT_FOUND;}
ng_status ng_relationship_get(const ng_graph*g,ng_relationship_id id,ng_relationship*out){size_t i;if(!g||!out)return NG_INVALID_ARGUMENT;for(i=0;i<g->nr;i++)if(g->re[i].id==id){out->id=g->re[i].id;out->source=g->re[i].src;out->target=g->re[i].dst;out->type=g->re[i].type;return NG_OK;}return NG_NOT_FOUND;}
static int rebuild_adjacency(ng_graph *g){size_t i,j,*counts;if(!g)return 0;free(g->ao);free(g->ai);g->ao=NULL;g->ai=NULL;g->an=0;if(!g->nn)return 1;counts=calloc(g->nn,sizeof(*counts));if(!counts)return 0;for(i=0;i<g->nr;i++)for(j=0;j<g->nn;j++)if(g->no[j].id==g->re[i].src||g->no[j].id==g->re[i].dst)counts[j]++;g->ao=calloc(g->nn+1,sizeof(*g->ao));if(!g->ao){free(counts);return 0;}for(i=0;i<g->nn;i++)g->ao[i+1]=g->ao[i]+counts[i];g->an=g->ao[g->nn];g->ai=malloc(g->an*sizeof(*g->ai));if(g->an&&!g->ai){free(counts);free(g->ao);g->ao=NULL;return 0;}memset(counts,0,g->nn*sizeof(*counts));for(i=0;i<g->nr;i++)for(j=0;j<g->nn;j++)if(g->no[j].id==g->re[i].src||g->no[j].id==g->re[i].dst)g->ai[g->ao[j]+counts[j]++]=i;free(counts);return 1;}
ng_status ng_node_relationships(const ng_graph*g,ng_node_id id,ng_direction d,ng_symbol_id type,ng_relationship_visitor visit,void *ctx){size_t i,j;ng_relationship r;ng_graph*x=(ng_graph*)g;if(!g||!visit||d>NG_DIRECTION_EITHER)return NG_INVALID_ARGUMENT;if(!node(x,id))return NG_NOT_FOUND;if(!rebuild_adjacency(x))return NG_OOM;for(j=0;j<g->nn;j++)if(g->no[j].id==id)for(i=g->ao[j];i<g->ao[j+1];i++){const rel_i*z=&g->re[g->ai[i]];int match=(d==NG_DIRECTION_OUTGOING?z->src==id:d==NG_DIRECTION_INCOMING?z->dst==id:(z->src==id||z->dst==id));if(match&&(!type||z->type==type)){r.id=z->id;r.source=z->src;r.target=z->dst;r.type=z->type;if(!visit(&r,ctx))return NG_OK;}}return NG_OK;}
ng_status ng_node_has_label(const ng_graph*g,ng_node_id id,ng_symbol_id label,int*out){size_t i;node_i*n;if(!g||!out||!label)return NG_INVALID_ARGUMENT;n=node((ng_graph*)g,id);if(!n)return NG_NOT_FOUND;*out=0;for(i=0;i<n->nl;i++)if(n->labels[i]==label){*out=1;break;}return NG_OK;}
ng_status ng_node_property(const ng_graph*g,ng_node_id id,ng_symbol_id key,ng_value*out){node_i*n;const prop*p;if(!g||!out||!key)return NG_INVALID_ARGUMENT;n=node((ng_graph*)g,id);if(!n)return NG_NOT_FOUND;p=findprop(n->p,n->np,key);if(!p)return NG_NOT_FOUND;*out=p->v;return NG_OK;}
ng_status ng_relationship_property(const ng_graph*g,ng_relationship_id id,ng_symbol_id key,ng_value*out){size_t i;const prop*p;if(!g||!out||!key)return NG_INVALID_ARGUMENT;for(i=0;i<g->nr;i++)if(g->re[i].id==id){p=findprop(g->re[i].p,g->re[i].np,key);if(!p)return NG_NOT_FOUND;*out=p->v;return NG_OK;}return NG_NOT_FOUND;}
ng_status ng_traverse(const ng_graph*g,ng_node_id start,const ng_traversal_options*o,ng_node_visitor visit,void*ctx){ng_node_id*q;uint32_t*d;unsigned char*seen;size_t head=0,tail=0,i,j;uint64_t count=0;ng_traversal_options def={NG_DIRECTION_EITHER,0,0,UINT32_MAX,0};if(!g||!visit)return NG_INVALID_ARGUMENT;if(!o)o=&def;if(o->direction>NG_DIRECTION_EITHER||(o->type_count&&!o->types))return NG_INVALID_ARGUMENT;if(!node((ng_graph*)g,start))return NG_NOT_FOUND;q=malloc(g->nn*sizeof(*q));d=malloc(g->nn*sizeof(*d));seen=calloc(g->nn,1);if((g->nn&&( !q||!d||!seen))){free(q);free(d);free(seen);return NG_OOM;}for(i=0;i<g->nn;i++)if(g->no[i].id==start){seen[i]=1;q[tail]=start;d[tail++]=0;break;}while(head<tail){ng_node_id cur=q[head];uint32_t depth=d[head++];if(o->visit_limit&&count>=o->visit_limit)break;count++;if(!visit(cur,depth,ctx))break;if(depth==o->max_depth)continue;for(i=0;i<g->nr;i++){const rel_i*r=&g->re[i];ng_node_id next=0;int dir=(o->direction==NG_DIRECTION_OUTGOING?r->src==cur:o->direction==NG_DIRECTION_INCOMING?r->dst==cur:(r->src==cur||r->dst==cur));if(!dir)continue;if(o->type_count){int ok=0;for(j=0;j<o->type_count;j++)if(o->types[j]==r->type){ok=1;break;}if(!ok)continue;}if(o->direction==NG_DIRECTION_INCOMING|| (o->direction==NG_DIRECTION_EITHER&&r->src!=cur))next=r->src;else next=r->dst;for(j=0;j<g->nn;j++)if(g->no[j].id==next&&!seen[j]){seen[j]=1;q[tail]=next;d[tail++]=depth+1;break;}}}free(q);free(d);free(seen);return NG_OK;}
const char *ng_symbol_name(const ng_graph*g,ng_symbol_id id){size_t i;if(!g)return NULL;for(i=0;i<g->ns;i++)if(g->sy[i].id==id)return g->sy[i].s;return NULL;}
ng_status ng_validate(const ng_graph*g){size_t i,j,k;if(!g)return NG_INVALID_ARGUMENT;if(!g->next_node||!g->next_rel||!g->next_sym)return NG_CORRUPT;for(i=0;i<g->ns;i++){if(!g->sy[i].id||!g->sy[i].s||!*g->sy[i].s||g->sy[i].id>=g->next_sym)return NG_CORRUPT;for(j=0;j<i;j++)if(g->sy[j].id==g->sy[i].id||!strcmp(g->sy[j].s,g->sy[i].s))return NG_CORRUPT;}for(i=0;i<g->nn;i++){if(!g->no[i].id||g->no[i].id>=g->next_node)return NG_CORRUPT;for(j=0;j<i;j++)if(g->no[j].id==g->no[i].id)return NG_CORRUPT;for(j=0;j<g->no[i].nl;j++){if(!g->no[i].labels[j]||!ng_symbol_name(g,g->no[i].labels[j]))return NG_CORRUPT;for(k=0;k<j;k++)if(g->no[i].labels[k]==g->no[i].labels[j])return NG_CORRUPT;}for(j=0;j<g->no[i].np;j++){if(!g->no[i].p[j].key||!ng_symbol_name(g,g->no[i].p[j].key)||!ng_valid_value(&g->no[i].p[j].v))return NG_CORRUPT;for(k=0;k<j;k++)if(g->no[i].p[k].key==g->no[i].p[j].key)return NG_CORRUPT;}}for(i=0;i<g->nr;i++){if(!g->re[i].id||g->re[i].id>=g->next_rel||!node((ng_graph*)g,g->re[i].src)||!node((ng_graph*)g,g->re[i].dst)||!ng_symbol_name(g,g->re[i].type))return NG_CORRUPT;for(j=0;j<i;j++)if(g->re[j].id==g->re[i].id)return NG_CORRUPT;for(j=0;j<g->re[i].np;j++){if(!g->re[i].p[j].key||!ng_symbol_name(g,g->re[i].p[j].key)||!ng_valid_value(&g->re[i].p[j].v))return NG_CORRUPT;for(k=0;k<j;k++)if(g->re[i].p[k].key==g->re[i].p[j].key)return NG_CORRUPT;}}for(i=0;i<g->nc;i++){if((g->co[i].kind!=NG_NODE_CONSTRAINT_REQUIRED_PROPERTY&&g->co[i].kind!=NG_NODE_CONSTRAINT_UNIQUE_PROPERTY)||!g->co[i].key||!ng_symbol_name(g,g->co[i].key)||(g->co[i].label&&!ng_symbol_name(g,g->co[i].label)))return NG_CORRUPT;for(j=0;j<i;j++)if(g->co[j].kind==g->co[i].kind&&g->co[j].label==g->co[i].label&&g->co[j].key==g->co[i].key)return NG_CORRUPT;}for(i=0;i<g->nix;i++){if(!g->ix[i].key||!ng_symbol_name(g,g->ix[i].key)||(g->ix[i].label&&!ng_symbol_name(g,g->ix[i].label)))return NG_CORRUPT;for(j=0;j<i;j++)if(g->ix[j].label==g->ix[i].label&&g->ix[j].key==g->ix[i].key)return NG_CORRUPT;}return ng_validate_constraints_all(g);}
const char *ng_status_name(ng_status s){static const char*n[]={[0]="ok","invalid argument","not found","parse error","exists","out of memory","io error","corrupt","limit"};return s<=NG_LIMIT?n[s]:"unknown";}
static int ng_value_equal(const ng_value*a,const ng_value*b){uint64_t x,y;if(!a||!b||a->type!=b->type)return 0;if(a->type==NG_VALUE_NULL)return 1;if(a->type==NG_VALUE_BOOL)return a->as.boolean==b->as.boolean;if(a->type==NG_VALUE_INT64)return a->as.integer==b->as.integer;if(a->type==NG_VALUE_DOUBLE){memcpy(&x,&a->as.real,8);memcpy(&y,&b->as.real,8);return x==y;}if(a->length!=b->length)return 0;if(a->type==NG_VALUE_STRING)return !a->length||!memcmp(a->as.string,b->as.string,a->length);if(a->type==NG_VALUE_BYTES)return !a->length||!memcmp(a->as.bytes,b->as.bytes,a->length);return 0;}
static int ng_node_matches_label(const node_i*n,ng_symbol_id label){size_t j;if(!label)return 1;for(j=0;j<n->nl;j++)if(n->labels[j]==label)return 1;return 0;}
ng_status ng_find_nodes(const ng_graph*g,ng_symbol_id label,ng_symbol_id key,const ng_value*v,ng_node_match_visitor visit,void*ctx){size_t i,j;if(!g||!v||!key||!visit)return NG_INVALID_ARGUMENT;if(v->type>NG_VALUE_BYTES)return NG_INVALID_ARGUMENT;for(i=0;i<g->nn;i++){int has=label==0;for(j=0;label&&j<g->no[i].nl;j++)if(g->no[i].labels[j]==label)has=1;if(has){const prop*p=findprop(g->no[i].p,g->no[i].np,key);if(p&&ng_value_equal(&p->v,v)&&!visit(g->no[i].id,ctx))break;}}return NG_OK;}
ng_status ng_require_node_property(const ng_graph*g,ng_symbol_id label,ng_symbol_id key,ng_node_id*out_node){size_t i;if(!g||!key)return NG_INVALID_ARGUMENT;if(label&&!ng_symbol_name(g,label))return NG_NOT_FOUND;if(!ng_symbol_name(g,key))return NG_NOT_FOUND;if(out_node)*out_node=0;for(i=0;i<g->nn;i++)if(ng_node_matches_label(&g->no[i],label)){const prop*p=findprop(g->no[i].p,g->no[i].np,key);if(!p||p->v.type==NG_VALUE_NULL){if(out_node)*out_node=g->no[i].id;return NG_NOT_FOUND;}}return NG_OK;}
ng_status ng_unique_node_property(const ng_graph*g,ng_symbol_id label,ng_symbol_id key,ng_node_id*out_first,ng_node_id*out_second){size_t i,j;if(!g||!key)return NG_INVALID_ARGUMENT;if(label&&!ng_symbol_name(g,label))return NG_NOT_FOUND;if(!ng_symbol_name(g,key))return NG_NOT_FOUND;if(out_first)*out_first=0;if(out_second)*out_second=0;for(i=0;i<g->nn;i++)if(ng_node_matches_label(&g->no[i],label)){const prop*a=findprop(g->no[i].p,g->no[i].np,key);if(!a||a->v.type==NG_VALUE_NULL)continue;for(j=i+1;j<g->nn;j++)if(ng_node_matches_label(&g->no[j],label)){const prop*b=findprop(g->no[j].p,g->no[j].np,key);if(b&&b->v.type!=NG_VALUE_NULL&&ng_value_equal(&a->v,&b->v)){if(out_first)*out_first=g->no[i].id;if(out_second)*out_second=g->no[j].id;return NG_EXISTS;}}}return NG_OK;}
static ng_status ng_check_one_constraint(const ng_graph*g,const constraint_i*c){ng_node_id a=0,b=0;if(c->kind==NG_NODE_CONSTRAINT_REQUIRED_PROPERTY)return ng_require_node_property(g,c->label,c->key,&a);if(c->kind==NG_NODE_CONSTRAINT_UNIQUE_PROPERTY)return ng_unique_node_property(g,c->label,c->key,&a,&b);return NG_CORRUPT;}
static ng_status ng_validate_constraints_all(const ng_graph*g){size_t i;ng_status s;if(!g)return NG_INVALID_ARGUMENT;for(i=0;i<g->nc;i++){s=ng_check_one_constraint(g,&g->co[i]);if(s!=NG_OK)return s;}return NG_OK;}
ng_status ng_node_constraint_create(ng_graph*g,ng_node_constraint_kind kind,ng_symbol_id label,ng_symbol_id key){size_t i;constraint_i c;ng_status s;if(!g||!key)return NG_INVALID_ARGUMENT;if(kind!=NG_NODE_CONSTRAINT_REQUIRED_PROPERTY&&kind!=NG_NODE_CONSTRAINT_UNIQUE_PROPERTY)return NG_INVALID_ARGUMENT;if(label&&!ng_symbol_name(g,label))return NG_NOT_FOUND;if(!ng_symbol_name(g,key))return NG_NOT_FOUND;for(i=0;i<g->nc;i++)if(g->co[i].kind==kind&&g->co[i].label==label&&g->co[i].key==key)return NG_EXISTS;c.kind=kind;c.label=label;c.key=key;s=ng_check_one_constraint(g,&c);if(s!=NG_OK)return s;if(!grow((void**)&g->co,&g->cc,g->nc+1,sizeof(*g->co)))return NG_OOM;g->co[g->nc++]=c;return NG_OK;}
ng_status ng_node_constraint_drop(ng_graph*g,ng_node_constraint_kind kind,ng_symbol_id label,ng_symbol_id key){size_t i;if(!g||!key)return NG_INVALID_ARGUMENT;for(i=0;i<g->nc;i++)if(g->co[i].kind==kind&&g->co[i].label==label&&g->co[i].key==key){if(i+1<g->nc)memmove(&g->co[i],&g->co[i+1],(g->nc-i-1)*sizeof(*g->co));g->nc--;return NG_OK;}return NG_NOT_FOUND;}
size_t ng_node_constraint_count(const ng_graph*g){return g?g->nc:0;}
ng_status ng_node_constraint_get(const ng_graph*g,size_t index,ng_node_constraint_kind*kind,ng_symbol_id*label,ng_symbol_id*key){if(!g||!kind||!label||!key)return NG_INVALID_ARGUMENT;if(index>=g->nc)return NG_NOT_FOUND;*kind=g->co[index].kind;*label=g->co[index].label;*key=g->co[index].key;return NG_OK;}
ng_status ng_node_index_create(ng_graph*g,ng_symbol_id label,ng_symbol_id key){size_t i;if(!g||!key)return NG_INVALID_ARGUMENT;if(label&&!ng_symbol_name(g,label))return NG_NOT_FOUND;if(!ng_symbol_name(g,key))return NG_NOT_FOUND;for(i=0;i<g->nix;i++)if(g->ix[i].label==label&&g->ix[i].key==key)return NG_EXISTS;if(!grow((void**)&g->ix,&g->cix,g->nix+1,sizeof(*g->ix)))return NG_OOM;g->ix[g->nix].label=label;g->ix[g->nix].key=key;g->nix++;return NG_OK;}
ng_status ng_node_index_drop(ng_graph*g,ng_symbol_id label,ng_symbol_id key){size_t i;if(!g||!key)return NG_INVALID_ARGUMENT;for(i=0;i<g->nix;i++)if(g->ix[i].label==label&&g->ix[i].key==key){if(i+1<g->nix)memmove(&g->ix[i],&g->ix[i+1],(g->nix-i-1)*sizeof(*g->ix));g->nix--;return NG_OK;}return NG_NOT_FOUND;}
size_t ng_node_index_count(const ng_graph*g){return g?g->nix:0;}
ng_status ng_node_index_get(const ng_graph*g,size_t index,ng_symbol_id*label,ng_symbol_id*key){if(!g||!label||!key)return NG_INVALID_ARGUMENT;if(index>=g->nix)return NG_NOT_FOUND;*label=g->ix[index].label;*key=g->ix[index].key;return NG_OK;}
static int ng_compare_index_entries(const void*a,const void*b){const ng_node_index_entry*x=(const ng_node_index_entry*)a,*y=(const ng_node_index_entry*)b;return x->id>y->id?1:x->id<y->id?-1:0;}
ng_status ng_node_index_build(const ng_graph*g,ng_symbol_id label,ng_symbol_id key,ng_node_index**out){ng_node_index*idx;size_t i,j;if(!g||!key||!out)return NG_INVALID_ARGUMENT;if(label&&!ng_symbol_name(g,label))return NG_NOT_FOUND;if(!ng_symbol_name(g,key))return NG_NOT_FOUND;idx=(ng_node_index*)calloc(1,sizeof(*idx));if(!idx)return NG_OOM;idx->label=label;idx->key=key;for(i=0;i<g->nn;i++){int has=label==0;const prop*p;for(j=0;label&&j<g->no[i].nl;j++)if(g->no[i].labels[j]==label)has=1;if(!has)continue;p=findprop(g->no[i].p,g->no[i].np,key);if(!p)continue;if(!grow((void**)&idx->entries,&idx->cap,idx->count+1,sizeof(*idx->entries))){ng_node_index_free(idx);return NG_OOM;}idx->entries[idx->count].id=g->no[i].id;if(valcopy(&idx->entries[idx->count].value,&p->v)!=NG_OK){ng_node_index_free(idx);return NG_OOM;}idx->count++;}qsort(idx->entries,idx->count,sizeof(*idx->entries),ng_compare_index_entries);*out=idx;return NG_OK;}
ng_status ng_node_index_find(const ng_node_index*idx,const ng_value*v,ng_node_match_visitor visit,void*ctx){size_t i;if(!idx||!v||!visit)return NG_INVALID_ARGUMENT;if(v->type>NG_VALUE_BYTES)return NG_INVALID_ARGUMENT;for(i=0;i<idx->count;i++)if(ng_value_equal(&idx->entries[i].value,v)&&!visit(idx->entries[i].id,ctx))break;return NG_OK;}
void ng_node_index_free(ng_node_index*idx){size_t i;if(!idx)return;for(i=0;i<idx->count;i++)valfree(&idx->entries[i].value);free(idx->entries);free(idx);}
#define NG_QUERY_MAX_TERMS 8
#define NG_QUERY_MAX_LIST_VALUES 8
#define NG_QUERY_MAX_EXPR 16
#define NG_QUERY_MAX_PROPS 8
typedef struct { char key[128]; ng_value value; } ng_query_prop;
typedef struct { char key[128], var; int is_id, connector, op, value_count; ng_value value, values[NG_QUERY_MAX_LIST_VALUES]; } ng_query_term;
typedef struct { int kind,left,right,term; } ng_query_expr;
typedef struct { char left_label[128],right_label[128],rel_type[128],key[128],return_key[128],return_keys[8][128],return_aliases[8][128],order_key[128],left_var_name[64],right_var_name[64],rel_var_name[64]; int has_relationship,has_second_node,has_where,where_is_id,has_limit,has_skip,has_order,order_is_property,order_is_id,order_desc,return_is_property,return_is_id,has_var_length,return_count,return_is_properties[8],return_is_ids[8],return_has_aliases[8],term_count,expr_count,where_root,rel_prop_count,rel_dir; char where_var,return_var,return_vars[8],order_var,rel_var; ng_query_term terms[NG_QUERY_MAX_TERMS]; ng_query_expr exprs[NG_QUERY_MAX_EXPR]; ng_query_prop rel_props[NG_QUERY_MAX_PROPS]; ng_value value; uint64_t limit,skip; uint32_t min_depth,max_depth; } ng_query_plan;
static const char *ng_skip_ws(const char*p){while(*p&&isspace((unsigned char)*p))p++;return p;}
static ng_symbol_id ng_symbol_id_by_text(const ng_graph*g,const char*s){size_t i;for(i=0;i<g->ns;i++)if(!strcmp(g->sy[i].s,s))return g->sy[i].id;return 0;}
static int ng_ident_char(int c){return isalnum((unsigned char)c)||c=='_';}
static ng_status ng_query_parse_prop_map(const char**pp,ng_query_prop*props,size_t*count);
static int ng_query_expr_add(ng_query_plan*plan,int kind,int left,int right,int term);
static ng_status ng_query_add_inline_props(ng_query_plan*plan,char role,const ng_query_prop*props,size_t prop_count){size_t i;int root=plan->where_root;for(i=0;i<prop_count;i++){ng_query_term*t;int term,node;if(plan->term_count>=NG_QUERY_MAX_TERMS)return NG_PARSE_ERROR;term=plan->term_count;t=&plan->terms[term];memset(t,0,sizeof(*t));t->var=role;t->op=0;t->value=props[i].value;strcpy(t->key,props[i].key);node=ng_query_expr_add(plan,0,-1,-1,term);if(node<0)return NG_PARSE_ERROR;plan->term_count++;root=root<0?node:ng_query_expr_add(plan,1,root,node,-1);if(root<0)return NG_PARSE_ERROR;if(term==0){plan->where_var=t->var;plan->where_is_id=t->is_id;strcpy(plan->key,t->key);plan->value=t->value;}}if(prop_count){plan->has_where=1;plan->where_root=root;}return NG_OK;}
static ng_status ng_query_parse_node_role(const char**pp,ng_query_plan*plan,char role,char*var,size_t var_capacity,char*label,size_t label_capacity){const char*p=*pp,*s;ng_query_prop props[NG_QUERY_MAX_PROPS];size_t n,prop_count=0;if(*p!='(')return NG_PARSE_ERROR;p++;p=ng_skip_ws(p);if(ng_ident_char((unsigned char)*p)&&!isdigit((unsigned char)*p)){s=p;while(ng_ident_char((unsigned char)*p))p++;n=(size_t)(p-s);if(n>=var_capacity)return NG_PARSE_ERROR;memcpy(var,s,n);var[n]=0;p=ng_skip_ws(p);}if(*p==':'){p++;s=p;while(ng_ident_char((unsigned char)*p))p++;n=(size_t)(p-s);if(!n||n>=label_capacity)return NG_PARSE_ERROR;memcpy(label,s,n);label[n]=0;p=ng_skip_ws(p);}if(ng_query_parse_prop_map(&p,props,&prop_count)!=NG_OK)return NG_PARSE_ERROR;if(ng_query_add_inline_props(plan,role,props,prop_count)!=NG_OK)return NG_PARSE_ERROR;p=ng_skip_ws(p);if(*p!=')')return NG_PARSE_ERROR;*pp=p+1;return NG_OK;}
static int ng_query_resolve_var(const ng_query_plan*plan,const char*name,char*out){if(!name||!*name||!out)return 0;if(plan->left_var_name[0]&&!strcmp(name,plan->left_var_name)){*out='n';return 1;}if(plan->right_var_name[0]&&!strcmp(name,plan->right_var_name)&&(plan->has_relationship||plan->has_second_node)){*out='m';return 1;}if(plan->rel_var_name[0]&&!strcmp(name,plan->rel_var_name)&&plan->has_relationship){*out='r';return 1;}return 0;}
static ng_status ng_query_parse_var_ref(const char**pp,const ng_query_plan*plan,char*out){const char*p=ng_skip_ws(*pp),*s;char name[64];size_t n;if(!ng_ident_char((unsigned char)*p)||isdigit((unsigned char)*p))return NG_PARSE_ERROR;s=p;while(ng_ident_char((unsigned char)*p))p++;n=(size_t)(p-s);if(!n||n>=sizeof(name))return NG_PARSE_ERROR;memcpy(name,s,n);name[n]=0;if(!ng_query_resolve_var(plan,name,out))return NG_PARSE_ERROR;*pp=p;return NG_OK;}
static ng_status ng_query_parse_value(const char**pp,ng_value*v){const char*p=ng_skip_ws(*pp);uint64_t mag=0,limit;int neg=0;if(*p=='"'){char*q;size_t n;p++;q=strchr(p,'"');if(!q)return NG_PARSE_ERROR;n=(size_t)(q-p);v->type=NG_VALUE_STRING;v->length=n;v->as.string=p;*pp=q+1;return NG_OK;}if(!strncmp(p,"true",4)&&!ng_ident_char((unsigned char)p[4])){v->type=NG_VALUE_BOOL;v->length=0;v->as.boolean=1;*pp=p+4;return NG_OK;}if(!strncmp(p,"false",5)&&!ng_ident_char((unsigned char)p[5])){v->type=NG_VALUE_BOOL;v->length=0;v->as.boolean=0;*pp=p+5;return NG_OK;}if(!strncmp(p,"null",4)&&!ng_ident_char((unsigned char)p[4])){v->type=NG_VALUE_NULL;v->length=0;*pp=p+4;return NG_OK;}if(*p=='-'){neg=1;p++;}if(!isdigit((unsigned char)*p))return NG_PARSE_ERROR;limit=neg?((uint64_t)INT64_MAX+1u):(uint64_t)INT64_MAX;while(isdigit((unsigned char)*p)){unsigned d=(unsigned)(*p-'0');if(mag>(limit-d)/10u)return NG_PARSE_ERROR;mag=mag*10u+d;p++;}v->type=NG_VALUE_INT64;v->length=0;v->as.integer=neg?(mag==(uint64_t)INT64_MAX+1u?INT64_MIN:-(int64_t)mag):(int64_t)mag;*pp=p;return NG_OK;}
static ng_status ng_query_parse_depth(const char**pp,ng_query_plan*plan){const char*p=*pp;uint64_t a=0,b=0;if(*p!='*')return NG_OK;p++;if(!isdigit((unsigned char)*p))return NG_PARSE_ERROR;while(isdigit((unsigned char)*p)){unsigned d=(unsigned)(*p-'0');if(a>(64-d)/10u)return NG_PARSE_ERROR;a=a*10u+d;p++;}b=a;if(p[0]=='.'&&p[1]=='.'){p+=2;if(!isdigit((unsigned char)*p))return NG_PARSE_ERROR;b=0;while(isdigit((unsigned char)*p)){unsigned d=(unsigned)(*p-'0');if(b>(64-d)/10u)return NG_PARSE_ERROR;b=b*10u+d;p++;}}if(a<1||b<a||b>64)return NG_PARSE_ERROR;plan->has_var_length=1;plan->min_depth=(uint32_t)a;plan->max_depth=(uint32_t)b;*pp=p;return NG_OK;}
static ng_status ng_query_parse_return_list(const char**pp,ng_query_plan*plan){const char*p=ng_skip_ws(*pp),*s;size_t n;if(strncmp(p,"RETURN",6)||!isspace((unsigned char)p[6]))return NG_PARSE_ERROR;p=ng_skip_ws(p+6);for(;;){int i=plan->return_count;if(i>=8)return NG_PARSE_ERROR;if(ng_query_parse_var_ref(&p,plan,&plan->return_vars[i])!=NG_OK)return NG_PARSE_ERROR;if(*p=='.'){p++;s=p;while(ng_ident_char((unsigned char)*p))p++;n=(size_t)(p-s);if(!n||n>=sizeof(plan->return_keys[i]))return NG_PARSE_ERROR;memcpy(plan->return_keys[i],s,n);plan->return_keys[i][n]=0;plan->return_is_properties[i]=1;if(!strcmp(plan->return_keys[i],"id"))plan->return_is_ids[i]=1;}p=ng_skip_ws(p);if(!strncmp(p,"AS",2)&&isspace((unsigned char)p[2])){p=ng_skip_ws(p+2);s=p;if(!ng_ident_char((unsigned char)*p)||isdigit((unsigned char)*p))return NG_PARSE_ERROR;while(ng_ident_char((unsigned char)*p))p++;n=(size_t)(p-s);if(!n||n>=sizeof(plan->return_aliases[i]))return NG_PARSE_ERROR;memcpy(plan->return_aliases[i],s,n);plan->return_aliases[i][n]=0;plan->return_has_aliases[i]=1;p=ng_skip_ws(p);}plan->return_count++;if(*p!=',')break;p=ng_skip_ws(p+1);}plan->return_var=plan->return_vars[0];strcpy(plan->return_key,plan->return_keys[0]);plan->return_is_property=plan->return_is_properties[0];plan->return_is_id=plan->return_is_ids[0];*pp=p;return NG_OK;}
static ng_status ng_query_parse_uint64(const char**pp,uint64_t*out){const char*p=ng_skip_ws(*pp);uint64_t v=0;if(!isdigit((unsigned char)*p))return NG_PARSE_ERROR;while(isdigit((unsigned char)*p)){unsigned d=(unsigned)(*p-'0');if(v>(UINT64_MAX-d)/10u)return NG_PARSE_ERROR;v=v*10u+d;p++;}*out=v;*pp=ng_skip_ws(p);return NG_OK;}
static ng_status ng_query_parse_order_by(const char**pp,ng_query_plan*plan){const char*p=ng_skip_ws(*pp),*s;size_t n;if(plan->has_order)return NG_PARSE_ERROR;if(ng_query_parse_var_ref(&p,plan,&plan->order_var)!=NG_OK)return NG_PARSE_ERROR;if(*p=='.'){p++;s=p;while(ng_ident_char((unsigned char)*p))p++;n=(size_t)(p-s);if(!n||n>=sizeof(plan->order_key))return NG_PARSE_ERROR;memcpy(plan->order_key,s,n);plan->order_key[n]=0;plan->order_is_property=1;if(!strcmp(plan->order_key,"id"))plan->order_is_id=1;}else plan->order_is_id=1;p=ng_skip_ws(p);if(!strncmp(p,"ASC",3)&&!ng_ident_char((unsigned char)p[3]))p=ng_skip_ws(p+3);else if(!strncmp(p,"DESC",4)&&!ng_ident_char((unsigned char)p[4])){plan->order_desc=1;p=ng_skip_ws(p+4);}plan->has_order=1;*pp=p;return NG_OK;}
static ng_status ng_query_parse_term(const char**pp,ng_query_plan*plan,int connector){const char*p=ng_skip_ws(*pp),*s;ng_query_term*t;size_t n;if(plan->term_count>=NG_QUERY_MAX_TERMS)return NG_PARSE_ERROR;t=&plan->terms[plan->term_count];memset(t,0,sizeof(*t));t->connector=connector;if(!strncmp(p,"id(",3)){p=ng_skip_ws(p+3);if(ng_query_parse_var_ref(&p,plan,&t->var)!=NG_OK)return NG_PARSE_ERROR;if(*p!=')')return NG_PARSE_ERROR;p++;t->is_id=1;strcpy(t->key,"id");}else{if(ng_query_parse_var_ref(&p,plan,&t->var)!=NG_OK)return NG_PARSE_ERROR;if(*p!='.')return NG_PARSE_ERROR;p++;s=p;while(ng_ident_char((unsigned char)*p))p++;n=(size_t)(p-s);if(!n||n>=sizeof(t->key))return NG_PARSE_ERROR;memcpy(t->key,s,n);t->key[n]=0;if(!strcmp(t->key,"id"))t->is_id=1;}p=ng_skip_ws(p);if(!strncmp(p,"<>",2)){t->op=2;p+=2;if(ng_query_parse_value(&p,&t->value)!=NG_OK)return NG_PARSE_ERROR;if(t->is_id&&t->value.type!=NG_VALUE_INT64)return NG_PARSE_ERROR;}else if(!strncmp(p,"<=",2)){t->op=4;p+=2;if(ng_query_parse_value(&p,&t->value)!=NG_OK)return NG_PARSE_ERROR;if(t->is_id&&t->value.type!=NG_VALUE_INT64)return NG_PARSE_ERROR;}else if(!strncmp(p,">=",2)){t->op=6;p+=2;if(ng_query_parse_value(&p,&t->value)!=NG_OK)return NG_PARSE_ERROR;if(t->is_id&&t->value.type!=NG_VALUE_INT64)return NG_PARSE_ERROR;}else if(*p=='<'){t->op=3;p++;if(ng_query_parse_value(&p,&t->value)!=NG_OK)return NG_PARSE_ERROR;if(t->is_id&&t->value.type!=NG_VALUE_INT64)return NG_PARSE_ERROR;}else if(*p=='>'){t->op=5;p++;if(ng_query_parse_value(&p,&t->value)!=NG_OK)return NG_PARSE_ERROR;if(t->is_id&&t->value.type!=NG_VALUE_INT64)return NG_PARSE_ERROR;}else if(*p=='='){t->op=0;p++;if(ng_query_parse_value(&p,&t->value)!=NG_OK)return NG_PARSE_ERROR;if(t->is_id&&t->value.type!=NG_VALUE_INT64)return NG_PARSE_ERROR;}else if(!strncmp(p,"IS",2)&&isspace((unsigned char)p[2])){p=ng_skip_ws(p+2);if(!strncmp(p,"NOT",3)&&isspace((unsigned char)p[3])){p=ng_skip_ws(p+3);if(strncmp(p,"NULL",4)||ng_ident_char((unsigned char)p[4]))return NG_PARSE_ERROR;t->op=8;p+=4;}else{if(strncmp(p,"NULL",4)||ng_ident_char((unsigned char)p[4]))return NG_PARSE_ERROR;t->op=7;p+=4;}}else if(!strncmp(p,"IN",2)&&isspace((unsigned char)p[2])){t->op=1;p=ng_skip_ws(p+2);if(*p!='[')return NG_PARSE_ERROR;p=ng_skip_ws(p+1);if(*p==']')return NG_PARSE_ERROR;for(;;){if(t->value_count>=NG_QUERY_MAX_LIST_VALUES)return NG_PARSE_ERROR;if(ng_query_parse_value(&p,&t->values[t->value_count])!=NG_OK)return NG_PARSE_ERROR;if(t->is_id&&t->values[t->value_count].type!=NG_VALUE_INT64)return NG_PARSE_ERROR;t->value_count++;p=ng_skip_ws(p);if(*p!=',')break;p=ng_skip_ws(p+1);}if(*p!=']')return NG_PARSE_ERROR;p++;t->value=t->values[0];}else return NG_PARSE_ERROR;if(plan->term_count==0){plan->where_var=t->var;plan->where_is_id=t->is_id;strcpy(plan->key,t->key);plan->value=t->value;}plan->term_count++;plan->has_where=1;*pp=ng_skip_ws(p);return NG_OK;}
static int ng_query_expr_add(ng_query_plan*plan,int kind,int left,int right,int term){int i=plan->expr_count;if(i>=NG_QUERY_MAX_EXPR)return -1;plan->exprs[i].kind=kind;plan->exprs[i].left=left;plan->exprs[i].right=right;plan->exprs[i].term=term;plan->expr_count++;return i;}
static ng_status ng_query_parse_or_expr(const char**pp,ng_query_plan*plan,int*out);
static ng_status ng_query_parse_primary_expr(const char**pp,ng_query_plan*plan,int*out){const char*p=ng_skip_ws(*pp);int node,term;if(!strncmp(p,"NOT",3)&&isspace((unsigned char)p[3])){int child;p=ng_skip_ws(p+3);if(ng_query_parse_primary_expr(&p,plan,&child)!=NG_OK)return NG_PARSE_ERROR;node=ng_query_expr_add(plan,3,child,-1,-1);if(node<0)return NG_PARSE_ERROR;*pp=p;*out=node;return NG_OK;}if(*p=='('){p=ng_skip_ws(p+1);if(ng_query_parse_or_expr(&p,plan,&node)!=NG_OK)return NG_PARSE_ERROR;p=ng_skip_ws(p);if(*p!=')')return NG_PARSE_ERROR;*pp=ng_skip_ws(p+1);*out=node;return NG_OK;}term=plan->term_count;if(ng_query_parse_term(&p,plan,0)!=NG_OK)return NG_PARSE_ERROR;node=ng_query_expr_add(plan,0,-1,-1,term);if(node<0)return NG_PARSE_ERROR;*pp=p;*out=node;return NG_OK;}
static ng_status ng_query_parse_and_expr(const char**pp,ng_query_plan*plan,int*out){const char*p=*pp;int left,right,node;if(ng_query_parse_primary_expr(&p,plan,&left)!=NG_OK)return NG_PARSE_ERROR;for(;;){p=ng_skip_ws(p);if(strncmp(p,"AND",3)||!isspace((unsigned char)p[3]))break;p=ng_skip_ws(p+3);if(ng_query_parse_primary_expr(&p,plan,&right)!=NG_OK)return NG_PARSE_ERROR;node=ng_query_expr_add(plan,1,left,right,-1);if(node<0)return NG_PARSE_ERROR;left=node;}*pp=p;*out=left;return NG_OK;}
static ng_status ng_query_parse_or_expr(const char**pp,ng_query_plan*plan,int*out){const char*p=*pp;int left,right,node;if(ng_query_parse_and_expr(&p,plan,&left)!=NG_OK)return NG_PARSE_ERROR;for(;;){p=ng_skip_ws(p);if(strncmp(p,"OR",2)||!isspace((unsigned char)p[2]))break;p=ng_skip_ws(p+2);if(ng_query_parse_and_expr(&p,plan,&right)!=NG_OK)return NG_PARSE_ERROR;node=ng_query_expr_add(plan,2,left,right,-1);if(node<0)return NG_PARSE_ERROR;left=node;}*pp=p;*out=left;return NG_OK;}
static ng_status ng_query_parse_where(const char**pp,ng_query_plan*plan){const char*p=*pp;int root;if(ng_query_parse_or_expr(&p,plan,&root)!=NG_OK)return NG_PARSE_ERROR;if(plan->where_root>=0){root=ng_query_expr_add(plan,1,plan->where_root,root,-1);if(root<0)return NG_PARSE_ERROR;}plan->where_root=root;plan->has_where=1;*pp=p;return NG_OK;}
static ng_status ng_query_parse_relationship_pattern(const char**pp,ng_query_plan*plan){const char*p=*pp,*s;size_t n,pc=0;if(*p=='<'){p++;if(*p!='-')return NG_PARSE_ERROR;plan->rel_dir=-1;p++;}else if(*p=='-'){plan->rel_dir=1;p++;}else return NG_PARSE_ERROR;if(*p!='[')return NG_PARSE_ERROR;p++;p=ng_skip_ws(p);if(ng_ident_char((unsigned char)*p)&&!isdigit((unsigned char)*p)){s=p;while(ng_ident_char((unsigned char)*p))p++;n=(size_t)(p-s);if(n>=sizeof(plan->rel_var_name))return NG_PARSE_ERROR;memcpy(plan->rel_var_name,s,n);plan->rel_var_name[n]=0;plan->rel_var='r';p=ng_skip_ws(p);}if(*p==':'){p++;s=p;while(ng_ident_char((unsigned char)*p))p++;n=(size_t)(p-s);if(!n||n>=sizeof(plan->rel_type))return NG_PARSE_ERROR;memcpy(plan->rel_type,s,n);plan->rel_type[n]=0;p=ng_skip_ws(p);}if(ng_query_parse_depth(&p,plan)!=NG_OK)return NG_PARSE_ERROR;p=ng_skip_ws(p);if(ng_query_parse_prop_map(&p,plan->rel_props,&pc)!=NG_OK)return NG_PARSE_ERROR;plan->rel_prop_count=(int)pc;p=ng_skip_ws(p);if(*p!=']')return NG_PARSE_ERROR;p++;if(plan->rel_dir<0){if(*p!='-')return NG_PARSE_ERROR;p++;}else{if(*p!='-')return NG_PARSE_ERROR;p++;if(*p=='>')p++;else plan->rel_dir=0;}*pp=p;return NG_OK;}
static ng_status ng_query_parse(const char*q,ng_query_plan*plan){const char*p;memset(plan,0,sizeof(*plan));plan->return_var='n';plan->where_var='n';plan->where_root=-1;plan->min_depth=1;plan->max_depth=1;plan->rel_dir=1;if(!q)return NG_INVALID_ARGUMENT;p=ng_skip_ws(q);if(strncmp(p,"MATCH",5)||!isspace((unsigned char)p[5]))return NG_PARSE_ERROR;p=ng_skip_ws(p+5);if(ng_query_parse_node_role(&p,plan,'n',plan->left_var_name,sizeof(plan->left_var_name),plan->left_label,sizeof(plan->left_label))!=NG_OK)return NG_PARSE_ERROR;if(*p=='-'||*p=='<'){if(ng_query_parse_relationship_pattern(&p,plan)!=NG_OK)return NG_PARSE_ERROR;if(ng_query_parse_node_role(&p,plan,'m',plan->right_var_name,sizeof(plan->right_var_name),plan->right_label,sizeof(plan->right_label))!=NG_OK)return NG_PARSE_ERROR;plan->has_relationship=1;}p=ng_skip_ws(p);if(!plan->has_relationship&&!strncmp(p,"MATCH",5)&&isspace((unsigned char)p[5])){p=ng_skip_ws(p+5);if(ng_query_parse_node_role(&p,plan,'m',plan->right_var_name,sizeof(plan->right_var_name),plan->right_label,sizeof(plan->right_label))!=NG_OK)return NG_PARSE_ERROR;plan->has_second_node=1;p=ng_skip_ws(p);}if(!strncmp(p,"WHERE",5)&&isspace((unsigned char)p[5])){p=ng_skip_ws(p+5);if(ng_query_parse_where(&p,plan)!=NG_OK)return NG_PARSE_ERROR;}if(ng_query_parse_return_list(&p,plan)!=NG_OK)return NG_PARSE_ERROR;p=ng_skip_ws(p);while(*p){if(!strncmp(p,"ORDER",5)&&isspace((unsigned char)p[5])){p=ng_skip_ws(p+5);if(strncmp(p,"BY",2)||!isspace((unsigned char)p[2]))return NG_PARSE_ERROR;p=ng_skip_ws(p+2);if(ng_query_parse_order_by(&p,plan)!=NG_OK)return NG_PARSE_ERROR;}else if(!strncmp(p,"SKIP",4)&&isspace((unsigned char)p[4])){if(plan->has_skip)return NG_PARSE_ERROR;p=ng_skip_ws(p+4);if(ng_query_parse_uint64(&p,&plan->skip)!=NG_OK)return NG_PARSE_ERROR;plan->has_skip=1;}else if(!strncmp(p,"LIMIT",5)&&isspace((unsigned char)p[5])){if(plan->has_limit)return NG_PARSE_ERROR;p=ng_skip_ws(p+5);if(ng_query_parse_uint64(&p,&plan->limit)!=NG_OK)return NG_PARSE_ERROR;plan->has_limit=1;}else return NG_PARSE_ERROR;p=ng_skip_ws(p);}return NG_OK;}
static int ng_node_has_label_id(const node_i*n,ng_symbol_id label){size_t i;if(!label)return 1;for(i=0;i<n->nl;i++)if(n->labels[i]==label)return 1;return 0;}
static int ng_query_label_matches(const node_i*n,ng_symbol_id label){return ng_node_has_label_id(n,label);}
static int ng_query_rel_matches_props(const rel_i*r,const ng_property*props,size_t prop_count){size_t i;if(!r)return 0;for(i=0;i<prop_count;i++){const prop*p=findprop(r->p,r->np,props[i].key);if(!p||!ng_value_equal(&p->v,&props[i].value))return 0;}return 1;}
static int ng_compare_values(const ng_value*a,const ng_value*b,int*out){int c;if(!a||!b||!out||a->type!=b->type)return 0;if(a->type==NG_VALUE_INT64)c=a->as.integer<b->as.integer?-1:a->as.integer>b->as.integer?1:0;else if(a->type==NG_VALUE_BOOL)c=a->as.boolean<b->as.boolean?-1:a->as.boolean>b->as.boolean?1:0;else if(a->type==NG_VALUE_STRING){size_t n=a->length<b->length?a->length:b->length;c=n?memcmp(a->as.string,b->as.string,n):0;if(!c)c=a->length<b->length?-1:a->length>b->length?1:0;}else return 0;*out=c;return 1;}
static int ng_query_compare_match(const ng_value*a,const ng_value*b,int op){int c;if(op==0)return ng_value_equal(a,b);if(op==2)return !ng_value_equal(a,b);if(!ng_compare_values(a,b,&c))return 0;if(op==3)return c<0;if(op==4)return c<=0;if(op==5)return c>0;if(op==6)return c>=0;return 0;}
static int ng_query_node_term_matches(const node_i*n,const ng_query_term*t,ng_symbol_id key){const prop*p;size_t i;ng_value idv;if(!n)return 0;if(t->is_id){idv.type=NG_VALUE_INT64;idv.length=0;idv.as.integer=(int64_t)n->id;if(t->op==7)return 0;if(t->op==8)return 1;if(t->op==1){for(i=0;i<(size_t)t->value_count;i++)if(ng_query_compare_match(&idv,&t->values[i],0))return 1;return 0;}return ng_query_compare_match(&idv,&t->value,t->op);}if(!key)return t->op==7;if(!key)return 0;p=findprop(n->p,n->np,key);if(!p)return t->op==7;if(t->op==7)return p->v.type==NG_VALUE_NULL;if(t->op==8)return p->v.type!=NG_VALUE_NULL;if(t->op==1){for(i=0;i<(size_t)t->value_count;i++)if(ng_value_equal(&p->v,&t->values[i]))return 1;return 0;}return ng_query_compare_match(&p->v,&t->value,t->op);}
static int ng_query_rel_term_matches(const rel_i*r,const ng_query_term*t,ng_symbol_id key){const prop*p;size_t i;ng_value idv;if(!r)return 0;if(t->is_id){idv.type=NG_VALUE_INT64;idv.length=0;idv.as.integer=(int64_t)r->id;if(t->op==7)return 0;if(t->op==8)return 1;if(t->op==1){for(i=0;i<(size_t)t->value_count;i++)if(ng_query_compare_match(&idv,&t->values[i],0))return 1;return 0;}return ng_query_compare_match(&idv,&t->value,t->op);}if(!key)return t->op==7;if(!key)return 0;p=findprop(r->p,r->np,key);if(!p)return t->op==7;if(t->op==7)return p->v.type==NG_VALUE_NULL;if(t->op==8)return p->v.type!=NG_VALUE_NULL;if(t->op==1){for(i=0;i<(size_t)t->value_count;i++)if(ng_value_equal(&p->v,&t->values[i]))return 1;return 0;}return ng_query_compare_match(&p->v,&t->value,t->op);}
static int ng_query_expr_matches(const ng_query_plan*plan,int expr,const node_i*left,const rel_i*rel,const node_i*right,const ng_symbol_id*term_keys){const ng_query_expr*e;const ng_query_term*t;const node_i*n;if(expr<0||expr>=plan->expr_count)return 0;e=&plan->exprs[expr];if(e->kind==1)return ng_query_expr_matches(plan,e->left,left,rel,right,term_keys)&&ng_query_expr_matches(plan,e->right,left,rel,right,term_keys);if(e->kind==2)return ng_query_expr_matches(plan,e->left,left,rel,right,term_keys)||ng_query_expr_matches(plan,e->right,left,rel,right,term_keys);if(e->kind==3)return !ng_query_expr_matches(plan,e->left,left,rel,right,term_keys);if(e->term<0||e->term>=plan->term_count)return 0;t=&plan->terms[e->term];if(t->var=='r')return ng_query_rel_term_matches(rel,t,term_keys[e->term]);n=t->var=='m'?right:left;return ng_query_node_term_matches(n,t,term_keys[e->term]);}
