static int ng_query_node_order_compare(const void*a,const void*b){const node_i*const*x=(const node_i*const*)a,*const*y=(const node_i*const*)b;ng_value ax,bx;const prop*ap,*bp;int c=0;if(ng_query_sort_plan->order_is_id||!ng_query_sort_plan->order_is_property){ax.type=NG_VALUE_INT64;ax.length=0;ax.as.integer=(int64_t)(*x)->id;bx.type=NG_VALUE_INT64;bx.length=0;bx.as.integer=(int64_t)(*y)->id;ng_compare_values(&ax,&bx,&c);}else{ap=findprop((*x)->p,(*x)->np,ng_query_sort_key);bp=findprop((*y)->p,(*y)->np,ng_query_sort_key);if(!ap&&!bp)c=0;else if(!ap)c=1;else if(!bp)c=-1;else if(!ng_compare_values(&ap->v,&bp->v,&c))c=0;}if(!c)c=(*x)->id>(*y)->id?1:(*x)->id<(*y)->id?-1:0;return ng_query_sort_plan->order_desc?-c:c;}
