ng_status ng_query_explain(const char*q,char*b,size_t c){ng_query_plan plan;ng_status s;int n;if(!q||!b||!c)return NG_INVALID_ARGUMENT;s=ng_query_parse(q,&plan);if(s!=NG_OK)return s;if(plan.has_relationship)n=snprintf(b,c,"Expand%s%s%s%s depth=%u..%u%s%s%s%s%s%s return=%c%s",plan.left_label[0]?" left_label=":"",plan.left_label[0]?plan.left_label:"",plan.rel_type[0]?" type=":"",plan.rel_type[0]?plan.rel_type:"",(unsigned)plan.min_depth,(unsigned)plan.max_depth,plan.right_label[0]?" right_label=":"",plan.right_label[0]?plan.right_label:"",plan.has_where?" filter=":"",plan.has_where?plan.key:"",plan.return_is_property?" project=.":"",plan.return_is_property?plan.return_key:"",plan.return_var,plan.has_limit?" limit":"");else n=snprintf(b,c,"NodeScan%s%s%s%s%s%s%s%s",plan.left_label[0]?" label=":"",plan.left_label[0]?plan.left_label:"",plan.has_where?" filter=n.":"",plan.has_where?plan.key:"",plan.has_where?" = <literal>":"",plan.return_is_property?" project=.":"",plan.return_is_property?plan.return_key:"",plan.has_limit?" limit":"");if(n<0)return NG_IO_ERROR;if((size_t)n>=c)return NG_LIMIT;return NG_OK;}

static int ng_print_value(FILE*out,const ng_value*v){size_t i;if(v->type==NG_VALUE_NULL)return fprintf(out,"null")>=0;if(v->type==NG_VALUE_BOOL)return fprintf(out,"%s",v->as.boolean?"true":"false")>=0;if(v->type==NG_VALUE_INT64)return fprintf(out,"%lld",(long long)v->as.integer)>=0;if(v->type==NG_VALUE_DOUBLE)return fprintf(out,"%.17g",v->as.real)>=0;if(v->type==NG_VALUE_STRING)return fwrite(v->as.string,1,v->length,out)==v->length;if(v->type==NG_VALUE_BYTES){if(fputs("0x",out)<0)return 0;for(i=0;i<v->length;i++)if(fprintf(out,"%02x",v->as.bytes[i])<0)return 0;return 1;}return 0;}
static ng_status ng_query_print_node_item(const node_i*n,const ng_query_plan*plan,size_t item,ng_symbol_id key,FILE*out){const prop*p;if(!n)return NG_INVALID_ARGUMENT;if(plan->return_is_ids[item]||!plan->return_is_properties[item])return fprintf(out,"%llu",(unsigned long long)n->id)<0?NG_IO_ERROR:NG_OK;p=findprop(n->p,n->np,key);if(!p)return NG_NOT_FOUND;if(!ng_print_value(out,&p->v))return NG_IO_ERROR;return NG_OK;}
