static ng_status ng_query_parse_prop_map(const char**pp,ng_query_prop*props,size_t*count){const char*p=ng_skip_ws(*pp),*s;size_t n;if(*p!='{'){*count=0;return NG_OK;}p=ng_skip_ws(p+1);*count=0;if(*p=='}'){*pp=p+1;return NG_OK;}for(;;){if(*count>=NG_QUERY_MAX_PROPS)return NG_PARSE_ERROR;s=p;if(!ng_ident_char((unsigned char)*p)||isdigit((unsigned char)*p))return NG_PARSE_ERROR;while(ng_ident_char((unsigned char)*p))p++;n=(size_t)(p-s);if(!n||n>=sizeof(props[*count].key))return NG_PARSE_ERROR;memcpy(props[*count].key,s,n);props[*count].key[n]=0;p=ng_skip_ws(p);if(*p!=':')return NG_PARSE_ERROR;p=ng_skip_ws(p+1);if(ng_query_parse_value(&p,&props[*count].value)!=NG_OK)return NG_PARSE_ERROR;(*count)++;p=ng_skip_ws(p);if(*p!=',')break;p=ng_skip_ws(p+1);}if(*p!='}')return NG_PARSE_ERROR;*pp=p+1;return NG_OK;}
