#define ng_import_property_graph ng_import_property_graph_impl
/* Property-graph TSV loader.  Node records are resolved before labels are
   processed; labels can therefore never allocate graph nodes. */
static char *ng_tab_field(char **cursor){char *s=*cursor,*q;if(!s)return NULL;q=strchr(s,'\t');if(q){*q=0;*cursor=q+1;}else *cursor=NULL;return s;}
static ng_status ng_import_node_for_id(ng_graph *g,ng_symbol_id external,const char *id,ng_node_id *out){size_t i;ng_value v;for(i=0;i<g->nn;i++){const prop*p=findprop(g->no[i].p,g->no[i].np,external);if(p&&p->v.type==NG_VALUE_STRING&&!strcmp(p->v.as.string,id)){*out=g->no[i].id;return NG_OK;}}if(ng_node_create(g,0,0,out)!=NG_OK)return NG_OOM;v.type=NG_VALUE_STRING;v.length=strlen(id);v.as.string=id;return ng_node_set(g,*out,external,&v);}
static ng_status ng_attach_labels(ng_graph *g,node_i *n,char *text){while(text&&*text){char *q=strchr(text,',');ng_symbol_id label;size_t i;if(q)*q=0;if(!*text)return NG_PARSE_ERROR;if(ng_symbol(g,text,&label)!=NG_OK)return NG_OOM;for(i=0;i<n->nl;i++)if(n->labels[i]==label)break;if(i==n->nl){if(!grow((void**)&n->labels,&n->cap,n->nl+1,sizeof(*n->labels)))return NG_OOM;n->labels[n->nl++]=label;}text=q?q+1:NULL;}return NG_OK;}
static int ng_hex(unsigned char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:-1;}
static ng_status ng_decode_hex(const char*t,size_t n,unsigned char**out,size_t*len){size_t i;unsigned char*p;if(n&1)return NG_PARSE_ERROR;if(n/2>SIZE_MAX)return NG_PARSE_ERROR;p=n?malloc(n/2):NULL;if(n&&!p)return NG_OOM;for(i=0;i<n/2;i++){int a=ng_hex((unsigned char)t[i*2]),b=ng_hex((unsigned char)t[i*2+1]);if(a<0||b<0){free(p);return NG_PARSE_ERROR;}p[i]=(unsigned char)((a<<4)|b);}*out=p;*len=n/2;return NG_OK;}
static ng_status ng_write_hex(FILE*f,const unsigned char*d,size_t n){static const char h[]="0123456789abcdef";size_t i;for(i=0;i<n;i++)if(fputc(h[d[i]>>4],f)==EOF||fputc(h[d[i]&15],f)==EOF)return NG_IO_ERROR;return NG_OK;}
static ng_status ng_write_encoded_value(FILE*f,const ng_value*v){uint64_t u;char b[32];if(!v)return NG_INVALID_ARGUMENT;if(v->type==NG_VALUE_NULL)return fputs("n",f)<0?NG_IO_ERROR:NG_OK;if(v->type==NG_VALUE_BOOL)return fputs(v->as.boolean?"b:1":"b:0",f)<0?NG_IO_ERROR:NG_OK;if(v->type==NG_VALUE_INT64){if(fputs("i:",f)<0)return NG_IO_ERROR;snprintf(b,sizeof(b),"%lld",(long long)v->as.integer);return fputs(b,f)<0?NG_IO_ERROR:NG_OK;}if(v->type==NG_VALUE_DOUBLE){memcpy(&u,&v->as.real,8);if(fprintf(f,"d:%016llx",(unsigned long long)u)<0)return NG_IO_ERROR;return NG_OK;}if(v->type==NG_VALUE_STRING){if(fputs("s:",f)<0)return NG_IO_ERROR;return ng_write_hex(f,(const unsigned char*)v->as.string,v->length);}if(v->type==NG_VALUE_BYTES){if(fputs("x:",f)<0)return NG_IO_ERROR;return ng_write_hex(f,v->as.bytes,v->length);}return NG_INVALID_ARGUMENT;}
static ng_status ng_parse_encoded_value(const char*t,size_t n,ng_value*out,void**owned){size_t i,z;int neg;uint64_t mag=0,limit;unsigned char*p;char*copy;ng_status s;if(!t||!out||!owned)return NG_INVALID_ARGUMENT;memset(out,0,sizeof(*out));*owned=NULL;if(n==1&&t[0]=='n'){out->type=NG_VALUE_NULL;return NG_OK;}if(n<3||t[1]!=':')return NG_PARSE_ERROR;if(t[0]=='b'){if(n!=3||(t[2]!='0'&&t[2]!='1'))return NG_PARSE_ERROR;out->type=NG_VALUE_BOOL;out->as.boolean=t[2]=='1';return NG_OK;}if(t[0]=='i'){if(n<3)return NG_PARSE_ERROR;i=2;neg=t[i]=='-';if(neg)i++;if(i==n)return NG_PARSE_ERROR;if((n-i)>1&&t[i]=='0')return NG_PARSE_ERROR;if(neg&&(n-i)==1&&t[i]=='0')return NG_PARSE_ERROR;limit=neg?((uint64_t)INT64_MAX+1u):(uint64_t)INT64_MAX;for(;i<n;i++){if(t[i]<'0'||t[i]>'9')return NG_PARSE_ERROR;if(mag>(limit-(uint64_t)(t[i]-'0'))/10u)return NG_PARSE_ERROR;mag=mag*10u+(uint64_t)(t[i]-'0');}out->type=NG_VALUE_INT64;out->as.integer=neg?(mag==(uint64_t)INT64_MAX+1u?INT64_MIN:-(int64_t)mag):(int64_t)mag;return NG_OK;}if(t[0]=='d'){uint64_t bits=0;int h;if(n!=18)return NG_PARSE_ERROR;for(i=2;i<18;i++){h=ng_hex((unsigned char)t[i]);if(h<0)return NG_PARSE_ERROR;bits=(bits<<4)|(unsigned)h;}out->type=NG_VALUE_DOUBLE;memcpy(&out->as.real,&bits,8);return NG_OK;}if(t[0]!='s'&&t[0]!='x')return NG_PARSE_ERROR;s=ng_decode_hex(t+2,n-2,&p,&z);if(s!=NG_OK)return s;if(t[0]=='s'){copy=malloc(z+1);if(z&&!copy){free(p);return NG_OOM;}if(z)memcpy(copy,p,z);copy[z]=0;free(p);out->type=NG_VALUE_STRING;out->length=z;out->as.string=copy;*owned=copy;}else{out->type=NG_VALUE_BYTES;out->length=z;out->as.bytes=p;*owned=p;}return NG_OK;}
size_t ng_test_encode_value(const ng_value*v,char*out,size_t cap){FILE*f;long n;size_t got;if(!v||!out||!cap)return 0;f=tmpfile();if(!f||ng_write_encoded_value(f,v)!=NG_OK){if(f)fclose(f);return 0;}if(fflush(f)!=0||fseek(f,0,SEEK_END)!=0){fclose(f);return 0;}n=ftell(f);if(n<0||(size_t)n+1>cap){fclose(f);return 0;}rewind(f);got=fread(out,1,(size_t)n,f);fclose(f);out[got]=0;return got;}
ng_status ng_test_decode_value(const char*t,ng_value*out,void**owned){return ng_parse_encoded_value(t,t?strlen(t):0,out,owned);}

static ng_status ng_attach_properties(ng_graph*g,ng_node_id id,char*text){while(text&&*text){char*semi=strchr(text,';'),*eq;ng_value v;void*owned=NULL;ng_symbol_id key;if(semi)*semi=0;eq=strchr(text,'=');if(!eq||eq==text)return NG_PARSE_ERROR;*eq=0;if(!strcmp(text,"__nautylus_external_id")){text=semi?semi+1:NULL;continue;}if(ng_symbol(g,text,&key)!=NG_OK)return NG_OOM;if(ng_parse_encoded_value(eq+1,strlen(eq+1),&v,&owned)!=NG_OK){free(owned);return NG_PARSE_ERROR;}if(ng_node_set(g,id,key,&v)!=NG_OK){free(owned);return NG_OOM;}free(owned);text=semi?semi+1:NULL;}return NG_OK;}

static ng_status ng_attach_relationship_properties(ng_graph*g,ng_relationship_id id,char*text){while(text&&*text){char*semi=strchr(text,';'),*eq;ng_value v;void*owned=NULL;ng_symbol_id key;if(semi)*semi=0;eq=strchr(text,'=');if(!eq||eq==text)return NG_PARSE_ERROR;*eq=0;if(ng_symbol(g,text,&key)!=NG_OK)return NG_OOM;if(ng_parse_encoded_value(eq+1,strlen(eq+1),&v,&owned)!=NG_OK){free(owned);return NG_PARSE_ERROR;}if(ng_relationship_set(g,id,key,&v)!=NG_OK){free(owned);return NG_OOM;}free(owned);text=semi?semi+1:NULL;}return NG_OK;}
static void ng_import_error(ng_import_diagnostic*d,size_t line,size_t column){if(d){d->line=line;d->column=column;d->status=NG_PARSE_ERROR;}}
ng_status ng_import_property_graph(ng_graph*g,const char*nodes_file,const char*relationships_file,int preserve_parallel,size_t*accepted,ng_import_diagnostic*d){FILE*f;ng_test_set_import_stage(NG_TEST_IMPORT_PARSE_NODES);char line[65536];size_t line_no=0,count=0;ng_symbol_id external;if(accepted)*accepted=0;if(d){d->line=0;d->column=0;d->status=NG_OK;}if(!g||!nodes_file||!relationships_file)return NG_INVALID_ARGUMENT;ng_test_set_import_stage(NG_TEST_IMPORT_SYMBOL);if(ng_symbol(g,"__nautylus_external_id",&external)!=NG_OK)return NG_OOM;f=fopen(nodes_file,"rb");if(!f)return NG_IO_ERROR;while(fgets(line,sizeof(line),f)){char *cursor=line,*kind,*id,*labels,*properties;size_t length=strlen(line);line_no++;while(length&&(line[length-1]=='\n'||line[length-1]=='\r'))line[--length]=0;kind=ng_tab_field(&cursor);id=ng_tab_field(&cursor);labels=ng_tab_field(&cursor);properties=cursor;if(!kind||strcmp(kind,"node")||!id||!*id||!labels||!properties){ng_import_error(d,line_no,1);fclose(f);return NG_PARSE_ERROR;}{ng_node_id node_id;ng_test_set_import_stage(NG_TEST_IMPORT_NODE);ng_status s=ng_import_node_for_id(g,external,id,&node_id);if(s!=NG_OK){fclose(f);return s;}node_i*n=node(g,node_id);ng_test_set_import_stage(NG_TEST_IMPORT_LABEL);s=ng_attach_labels(g,n,labels);if(s!=NG_OK){ng_import_error(d,line_no,1);fclose(f);return s;}ng_test_set_import_stage(NG_TEST_IMPORT_NODE_PROPERTY);s=ng_attach_properties(g,node_id,properties);if(s!=NG_OK){ng_import_error(d,line_no,1);fclose(f);return s;}count++;}}fclose(f);ng_test_set_import_stage(NG_TEST_IMPORT_PARSE_RELATIONSHIPS);f=fopen(relationships_file,"rb");if(!f)return NG_IO_ERROR;while(fgets(line,sizeof(line),f)){char *cursor=line,*kind,*rid,*source,*type,*target,*properties;size_t length=strlen(line),i;line_no++;while(length&&(line[length-1]=='\n'||line[length-1]=='\r'))line[--length]=0;kind=ng_tab_field(&cursor);rid=ng_tab_field(&cursor);source=ng_tab_field(&cursor);type=ng_tab_field(&cursor);target=ng_tab_field(&cursor);properties=cursor;if(!kind||strcmp(kind,"relationship")||!rid||!source||!type||!target||!properties){ng_import_error(d,line_no,1);fclose(f);return NG_PARSE_ERROR;}ng_node_id a=0,b=0;for(i=0;i<g->nn;i++){const prop*p=findprop(g->no[i].p,g->no[i].np,external);if(p&&p->v.type==NG_VALUE_STRING){if(!strcmp(p->v.as.string,source))a=g->no[i].id;if(!strcmp(p->v.as.string,target))b=g->no[i].id;}}if(!a||!b){fclose(f);return NG_NOT_FOUND;}ng_symbol_id relation_type;ng_test_set_import_stage(NG_TEST_IMPORT_SYMBOL);if(ng_symbol(g,type,&relation_type)!=NG_OK){fclose(f);return NG_OOM;}if(!preserve_parallel){int duplicate=0;for(i=0;i<g->nr;i++)if(g->re[i].src==a&&g->re[i].dst==b&&g->re[i].type==relation_type){duplicate=1;break;}if(duplicate)continue;}ng_test_set_import_stage(NG_TEST_IMPORT_RELATIONSHIP);ng_relationship_id relation_id;if(ng_relationship_create(g,a,relation_type,b,&relation_id)!=NG_OK){fclose(f);return NG_OOM;}if(properties&&*properties){ng_test_set_import_stage(NG_TEST_IMPORT_RELATIONSHIP_PROPERTY);ng_status s=ng_attach_relationship_properties(g,relation_id,properties);if(s!=NG_OK){ng_import_error(d,line_no,1);fclose(f);return s;}}count++;}fclose(f);if(accepted)*accepted=count;ng_test_set_import_stage(NG_TEST_IMPORT_COMPLETE);return NG_OK;}
