static void ng_free_contents(ng_graph*g){size_t i,j;if(!g)return;for(i=0;i<g->ns;i++)free(g->sy[i].s);for(i=0;i<g->nn;i++){free(g->no[i].labels);for(j=0;j<g->no[i].np;j++)valfree(&g->no[i].p[j].v);free(g->no[i].p);}for(i=0;i<g->nr;i++){for(j=0;j<g->re[i].np;j++)valfree(&g->re[i].p[j].v);free(g->re[i].p);}free(g->sy);free(g->no);free(g->re);free(g->co);free(g->ix);free(g->path);free(g->ao);free(g->ai);memset(g,0,sizeof(*g));}
static int ng_clone_graph(const ng_graph*src,ng_graph*dst){size_t i,j;memset(dst,0,sizeof(*dst));dst->path=dupstr(src->path);dst->next_node=src->next_node;dst->next_rel=src->next_rel;dst->next_sym=src->next_sym;if(!dst->path)return 0;for(i=0;i<src->ns;i++){if(!grow((void**)&dst->sy,&dst->cs,dst->ns+1,sizeof(*dst->sy)))return 0;dst->sy[dst->ns].id=src->sy[i].id;dst->sy[dst->ns].s=dupstr(src->sy[i].s);if(!dst->sy[dst->ns].s)return 0;dst->ns++;}for(i=0;i<src->nn;i++){node_i*n=&dst->no[dst->nn];if(!grow((void**)&dst->no,&dst->cn,dst->nn+1,sizeof(*dst->no)))return 0;n=&dst->no[dst->nn++];memset(n,0,sizeof(*n));n->id=src->no[i].id;if(src->no[i].nl){n->labels=malloc(src->no[i].nl*sizeof(*n->labels));if(!n->labels)return 0;memcpy(n->labels,src->no[i].labels,src->no[i].nl*sizeof(*n->labels));n->nl=src->no[i].nl;n->cap=n->nl;}for(j=0;j<src->no[i].np;j++){if(!grow((void**)&n->p,&n->cap,n->np+1,sizeof(*n->p)))return 0;n->p[n->np]=src->no[i].p[j];if(src->no[i].p[j].v.type==NG_VALUE_STRING){n->p[n->np].v.as.string=dupstr(src->no[i].p[j].v.as.string);if(!n->p[n->np].v.as.string)return 0;}else if(src->no[i].p[j].v.type==NG_VALUE_BYTES){n->p[n->np].v.as.bytes=(unsigned char*)malloc(n->p[n->np].v.length);if(n->p[n->np].v.length&&!n->p[n->np].v.as.bytes)return 0;memcpy((void*)n->p[n->np].v.as.bytes,src->no[i].p[j].v.as.bytes,n->p[n->np].v.length);}n->np++;}}for(i=0;i<src->nr;i++){rel_i*r;if(!grow((void**)&dst->re,&dst->cr,dst->nr+1,sizeof(*dst->re)))return 0;r=&dst->re[dst->nr++];memset(r,0,sizeof(*r));*r=src->re[i];r->p=NULL;r->cap=r->np=0;for(j=0;j<src->re[i].np;j++){if(!grow((void**)&r->p,&r->cap,r->np+1,sizeof(*r->p)))return 0;r->p[r->np]=src->re[i].p[j];if(src->re[i].p[j].v.type==NG_VALUE_STRING){r->p[r->np].v.as.string=dupstr(src->re[i].p[j].v.as.string);if(!r->p[r->np].v.as.string)return 0;}else if(src->re[i].p[j].v.type==NG_VALUE_BYTES){r->p[r->np].v.as.bytes=(unsigned char*)malloc(r->p[r->np].v.length);if(r->p[r->np].v.length&&!r->p[r->np].v.as.bytes)return 0;memcpy((void*)r->p[r->np].v.as.bytes,src->re[i].p[j].v.as.bytes,r->p[r->np].v.length);}r->np++;}}if(src->nc){dst->co=(constraint_i*)malloc(src->nc*sizeof(*dst->co));if(!dst->co)return 0;memcpy(dst->co,src->co,src->nc*sizeof(*dst->co));dst->nc=dst->cc=src->nc;}if(src->nix){dst->ix=(index_i*)malloc(src->nix*sizeof(*dst->ix));if(!dst->ix)return 0;memcpy(dst->ix,src->ix,src->nix*sizeof(*dst->ix));dst->nix=dst->cix=src->nix;}return 1;}
ng_status ng_import_triples(ng_graph*g,const char*file,int preserve_parallel,size_t*accepted){ng_graph snapshot;ng_status s;if(!g||!file)return NG_INVALID_ARGUMENT;if(!ng_clone_graph(g,&snapshot)){ng_free_contents(&snapshot);if(accepted)*accepted=0;return NG_OOM;}s=ng_import_triples_impl(g,file,preserve_parallel,accepted);if(s==NG_OK)s=ng_validate(g);if(s!=NG_OK){ng_graph failed=*g;*g=snapshot;ng_free_contents(&failed);if(accepted)*accepted=0;}else{ng_free_contents(&snapshot);}return s;}
ng_status ng_import_triples_csv(ng_graph*g,const char*file,int preserve_parallel,size_t*accepted){ng_graph snapshot;ng_status s;if(!g||!file)return NG_INVALID_ARGUMENT;if(!ng_clone_graph(g,&snapshot)){ng_free_contents(&snapshot);if(accepted)*accepted=0;return NG_OOM;}s=ng_import_triples_csv_impl(g,file,preserve_parallel,accepted);if(s==NG_OK)s=ng_validate(g);if(s!=NG_OK){ng_graph failed=*g;*g=snapshot;ng_free_contents(&failed);if(accepted)*accepted=0;}else{ng_free_contents(&snapshot);}return s;}
ng_status ng_import_property_graph(ng_graph*g,const char*n,const char*r,int p,size_t*a,ng_import_diagnostic*d){ng_graph snapshot;ng_status s;ng_test_import_stage=NG_TEST_IMPORT_NONE;ng_test_import_stage_mask_value=0;if(!g)return NG_INVALID_ARGUMENT;ng_test_set_import_stage(NG_TEST_IMPORT_SNAPSHOT);if(!ng_clone_graph(g,&snapshot)){ng_free_contents(&snapshot);if(a)*a=0;if(d){d->line=0;d->column=0;d->status=NG_OOM;}return NG_OOM;}s=ng_import_property_graph_impl(g,n,r,p,a,d);if(s==NG_OK)s=ng_validate(g);if(s!=NG_OK){if(a)*a=0;if(d&&s==NG_OOM){d->line=0;d->column=0;d->status=NG_OOM;}ng_graph failed=*g;*g=snapshot;ng_free_contents(&failed);}else{ng_free_contents(&snapshot);}return s;}
ng_status ng_transaction_begin(ng_graph*g,ng_transaction**out){ng_transaction*tx;if(!g||!out)return NG_INVALID_ARGUMENT;tx=(ng_transaction*)calloc(1,sizeof(*tx));if(!tx)return NG_OOM;tx->target=g;tx->active=1;if(!ng_clone_graph(g,&tx->working)){ng_free_contents(&tx->working);free(tx);return NG_OOM;}*out=tx;return NG_OK;}
ng_graph *ng_transaction_graph(ng_transaction*tx){return tx&&tx->active?&tx->working:NULL;}
ng_status ng_transaction_commit(ng_transaction*tx){ng_graph old;ng_status s;if(!tx||!tx->active)return NG_INVALID_ARGUMENT;s=ng_validate(&tx->working);if(s!=NG_OK)return s;old=*tx->target;*tx->target=tx->working;memset(&tx->working,0,sizeof(tx->working));tx->active=0;ng_free_contents(&old);free(tx);return NG_OK;}
void ng_transaction_rollback(ng_transaction*tx){if(!tx)return;if(tx->active)ng_free_contents(&tx->working);free(tx);}
static int ng_export_safe_text(const char*s){return s&&!strpbrk(s,"\t\r\n,;=");}
static int ng_compare_symbol_ids(const void*a,const void*b){ng_symbol_id x=*(const ng_symbol_id*)a,y=*(const ng_symbol_id*)b;return x>y?1:x<y?-1:0;}
static int ng_compare_property_indexes(const void*a,const void*b){const prop*x=*(const prop*const*)a,*y=*(const prop*const*)b;return x->key>y->key?1:x->key<y->key?-1:0;}
static int ng_export_value(FILE*f,const ng_graph*g,const prop*p){const char*k=ng_symbol_name(g,p->key);if(!ng_export_safe_text(k))return 0;return fprintf(f,"%s=",k)>=0&&ng_write_encoded_value(f,&p->v)==NG_OK;}
static ng_status ng_export_props(FILE*f,const ng_graph*g,const prop*p,size_t n){const prop**v=NULL;size_t i;if(n>1){if(n>SIZE_MAX/sizeof(*v))return NG_OOM;if(ng_test_maybe_fail()!=NG_OK)return NG_OOM;v=malloc(n*sizeof(*v));if(!v)return NG_OOM;for(i=0;i<n;i++)v[i]=&p[i];qsort(v,n,sizeof(*v),ng_compare_property_indexes);}for(i=0;i<n;i++){const prop*x=n>1?v[i]:&p[i];if(i&&fputc(';',f)==EOF){free(v);return NG_IO_ERROR;}if(!ng_export_value(f,g,x)){free(v);return NG_INVALID_ARGUMENT;}}free(v);return NG_OK;}
static int ng_path_exists(const char*p){FILE*f=fopen(p,"rb");if(f){fclose(f);return 1;}return 0;}
static int ng_backup_existing(const char*path,const char*backup,int*had){*had=0;if(ng_path_exists(backup))return 0;if(rename(path,backup)==0){*had=1;return 1;}return errno==ENOENT;}
static void ng_restore_backup(const char*path,const char*backup,int had){if(had){remove(path);rename(backup,path);}else remove(path);}
static ng_status ng_commit_pair(const char*nt,const char*rt,const char*nodes_file,const char*relationships_file,const char*nb,const char*rb){int nhad=0,rhad=0;if(!ng_backup_existing(nodes_file,nb,&nhad))return NG_IO_ERROR;if(!ng_backup_existing(relationships_file,rb,&rhad)){ng_restore_backup(nodes_file,nb,nhad);return NG_IO_ERROR;}if(rename(nt,nodes_file)!=0){ng_restore_backup(nodes_file,nb,nhad);ng_restore_backup(relationships_file,rb,rhad);return NG_IO_ERROR;}if(rename(rt,relationships_file)!=0){ng_restore_backup(nodes_file,nb,nhad);ng_restore_backup(relationships_file,rb,rhad);return NG_IO_ERROR;}remove(nb);remove(rb);return NG_OK;}
ng_status ng_export_property_graph(const ng_graph*g,const char*nodes_file,const char*relationships_file){
    FILE*nf=NULL,*rf=NULL;
    char nt[4096],rt[4096],nb[4096],rb[4096];
    size_t i,j;
    ng_id last;
    const char*name;
    ng_status st;
    if(!g||!nodes_file||!relationships_file)return NG_INVALID_ARGUMENT;
    if(!strcmp(nodes_file,relationships_file))return NG_INVALID_ARGUMENT;
    if(strlen(nodes_file)>sizeof(nt)-11||strlen(relationships_file)>sizeof(rt)-11)return NG_INVALID_ARGUMENT;
    snprintf(nt,sizeof(nt),"%s.tmp",nodes_file);
    snprintf(rt,sizeof(rt),"%s.tmp",relationships_file);
    snprintf(nb,sizeof(nb),"%s.nautylusbak",nodes_file);
    snprintf(rb,sizeof(rb),"%s.nautylusbak",relationships_file);
    if(!strcmp(nt,rt)||!strcmp(nb,rb)||!strcmp(nt,nodes_file)||!strcmp(rt,relationships_file))return NG_INVALID_ARGUMENT;
    if(ng_path_exists(nb)||ng_path_exists(rb))return NG_EXISTS;
    nf=fopen(nt,"wb");if(!nf)goto io;
    rf=fopen(rt,"wb");if(!rf)goto io;
    for(last=0;;){
        ng_node_id id=0;
        for(i=0;i<g->nn;i++)if(g->no[i].id>last&&(!id||g->no[i].id<id))id=g->no[i].id;
        if(!id)break;
        last=id;
        for(i=0;i<g->nn;i++)if(g->no[i].id==id){
            ng_symbol_id*labels=NULL;
            size_t nl=g->no[i].nl;
            if(nl>1){
                if(nl>SIZE_MAX/sizeof(*labels)){st=NG_OOM;goto fail;}
                if(ng_test_maybe_fail()!=NG_OK){st=NG_OOM;goto fail;}
                labels=malloc(nl*sizeof(*labels));
                if(!labels){st=NG_OOM;goto fail;}
                memcpy(labels,g->no[i].labels,nl*sizeof(*labels));
                qsort(labels,nl,sizeof(*labels),ng_compare_symbol_ids);
            }
            if(fprintf(nf,"node\t%llu\t",(unsigned long long)id)<0){free(labels);goto io;}
            for(j=0;j<nl;j++){
                name=ng_symbol_name(g,nl>1?labels[j]:g->no[i].labels[j]);
                if(!ng_export_safe_text(name)||(j&&fputc(',',nf)==EOF)||fputs(name,nf)<0){free(labels);goto unsupported;}
            }
            free(labels);
            if(fputc('\t',nf)==EOF)goto io;
            st=ng_export_props(nf,g,g->no[i].p,g->no[i].np);
            if(st!=NG_OK)goto fail;
            if(fputc('\n',nf)==EOF)goto io;
            break;
        }
    }
    for(last=0;;){
        ng_relationship_id id=0;
        for(i=0;i<g->nr;i++)if(g->re[i].id>last&&(!id||g->re[i].id<id))id=g->re[i].id;
        if(!id)break;
        last=id;
        for(i=0;i<g->nr;i++)if(g->re[i].id==id){
            name=ng_symbol_name(g,g->re[i].type);
            if(!ng_export_safe_text(name))goto unsupported;
            if(fprintf(rf,"relationship\t%llu\t%llu\t%s\t%llu\t",(unsigned long long)id,(unsigned long long)g->re[i].src,name,(unsigned long long)g->re[i].dst)<0)goto io;
            st=ng_export_props(rf,g,g->re[i].p,g->re[i].np);
            if(st!=NG_OK)goto fail;
            if(fputc('\n',rf)==EOF)goto io;
            break;
        }
    }
    if(fclose(nf)!=0){nf=NULL;goto io_closed;}nf=NULL;
    if(fclose(rf)!=0){rf=NULL;goto io_closed;}rf=NULL;
    st=ng_commit_pair(nt,rt,nodes_file,relationships_file,nb,rb);
    if(st!=NG_OK)goto fail_closed;
    return NG_OK;
unsupported:
    st=NG_INVALID_ARGUMENT;
    goto fail;
fail:
    if(nf)fclose(nf);
    if(rf)fclose(rf);
    remove(nt);
    remove(rt);
    return st;
io:
    if(nf)fclose(nf);
    if(rf)fclose(rf);
io_closed:
    st=NG_IO_ERROR;
fail_closed:
    remove(nt);
    remove(rt);
    return st;
}
